(window.__BOOKS=window.__BOOKS||{})["e_helena"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Елена, спартанская царица</span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Тевкр, саламинский царевич, изгнанник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор пленных гречанок</span>"],["person","<span class=\"pn\">Менелай, муж <span class=\"ch\" data-ch=\"elena\">Елены</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Привратница пророчицы <span class=\"ch\" data-ch=\"feonoya\">Феонои</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Слуга <span class=\"ch\" data-ch=\"menelay\">Менелая</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Феоноя, пророчица</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Феоклимен, египетский царь, брат <span class=\"ch\" data-ch=\"feonoya\">Феонои</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Вестник, воин <span class=\"ch\" data-ch=\"feoklimen\">Феоклимена</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Диоскуры Кастор и Поллукс</span> <span class=\"act-no\">(I)</span>"],["place","Действие происходит в Египте, близ моря, вскоре после падения Трои. На переднем плане сцены строгая гробница покойного царя Протея; за нею стена кремля киклопической кладки, с зубцами. Ворота настежь открыты. Далее холм, на котором возвышается дворец Феоклимена; его двери заперты."],["act","Пролог","a1",""],["scene","Явление первое","s1",1,1],["sd","Перед гробницею на ложе из листьев и ветвей <span class=\"ch\" data-ch=\"elena\">Елена</span>. Утро. Царица поднимается с ложа."],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Здесь блещут Нила девственные волны;",0,1,0,0],["v","Взамен росы небесной он поит,",0,1,0,0],["v","Лишь снег сойдет, в Египте по низинам",0,1,0,0],["v","Лежащие поля. При жизни здесь<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,2,0,0],["v","Протей царил, и если Фарос домом,",0,3,0,0],["v","То весь ему Египет царством был;",0,4,0,0],["v","А браком царь с одной из дев пучинных,",0,5,0,0],["v","Псамафой, сочетался, для него",0,6,0,0],["v","Эаково покинувшею ложе.<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,7,0,0],["v","И родила царю двоих детей",0,8,0,0],["v","Его жена: <span class=\"ch\" data-ch=\"feoklimen\">Феоклимена</span>-сына",0,9,0,0],["v","И благородную Идо; дитятей",0,10,0,1],["v","Она отрадой матери была,",0,10,0,0],["v","А брачных лет достигши, <span class=\"ch\" data-ch=\"feonoya\">Феоноей</span>",0,11,0,0],["v","Наречена, затем, что от богов",0,12,0,0],["v","И все, что есть, и все, что будет, ей<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,13,0,0],["v","Открыто; эту честь она приемлет",0,13,0,0],["v","От древнего Нерея, деда…",0,14,0,0],["v","Мне",1,14,0,0],["v","Отечество на долю не без славы<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,15,0,0],["v","Досталось тоже — Спарта; и Тиндар",0,16,0,0],["v","Был мне отцом… Положим, существует",0,16,0,0],["v","Предание, что сам отец богов",0,17,0,0],["v","Когда-то мать мою крылами обнял,",0,18,0,0],["v","Что, лебедем прикинувшись, на лоне",0,19,0,0],["v","Ее он скрылся, подавая вид,",0,20,0,1],["v","Что от орла спасается… так молвят.",0,20,0,0],["v","Я названа <span class=\"ch\" data-ch=\"elena\">Еленой</span>, и моя",0,21,0,0],["v","Вот горестная повесть:",0,22,0,0],["v","Три богини,",1,22,0,0],["v","О красоте заспоривши, пришли",0,22,0,0],["v","В идейское ущелье к Александру.",0,23,0,0],["v","С Кипридою была там Гера, дочь",0,24,0,0],["v","Чистейшая Кронида с ними, — должен",0,25,0,0],["v","Был разрешить их распрю волопас.",0,25,0,0],["v","И вот, мою красу (коль и несчастье",0,26,0,0],["v","Прекрасным может быть) пообещав",0,27,0,0],["v","Для ложа Александру, побеждает",0,27,0,0],["v","Киприда, а Парис-Идей, покинув<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,28,0,0],["v","Пастушеский загон, стремится в Спарту,",0,29,0,0],["v","Чтоб овладеть невестой.",0,30,0,1],["v","Но своей",1,30,0,0],["v","Не вынесла обиды Гера — ложе",0,30,0,0],["v","Парисовой утехи обратила",0,31,0,0],["v","Она в ничто, и не меня женой",0,32,0,0],["v","Он получил, нет: призрак из эфира",0,33,0,0],["v","Чистейшего, по моему подобью,",0,33,0,0],["v","Был Герою для Приамида слажен,",0,34,0,0],["v","Царевича троянского. Меня",0,35,0,0],["v","Он обнимал, но в мыслях лишь, пустое",0,36,0,0],["v","То было обольщенье. Зевса же",0,36,0,0],["v","Свершалася другая воля к вящей",0,37,0,0],["v","Беде моей: меж греков и несчастных",0,38,0,0],["v","Фригийцев он войну зажег, чтоб мать",0,39,0,0],["v","Освободить от населенья — Землю —",0,40,0,1],["v","Чрезмерного и чтобы лучший грек",0,40,0,0],["v","Был славою отмечен. Битв наградой<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,41,0,0],["v","Троянам и ахейцам он назначил",0,42,0,0],["v","Меня… Меня? О нет! Лишь звук пустой",0,42,0,0],["v","Носился над войсками, а меня,",0,43,0,0],["v","Среди морщин эфирных затаив",0,44,0,0],["v","И тучею одев, Гермес похитил —",0,45,0,0],["v","Зевс не забыл меня — и в дом Протея",0,45,0,0],["v","Меня унес, его считая всех",0,46,0,0],["v","Воздержнее, чтоб я осталась чистой",0,47,0,0],["v","Для ложа <span class=\"ch\" data-ch=\"menelay\">Менелая</span>.",0,47,0,0],["v","С той поры",1,47,0,0],["v","Я здесь живу, а муж мой злополучный,",0,48,0,0],["v","Войска собрав, на Илион повел",0,49,0,0],["v","И ищет там жены своей, добычу",0,50,0,1],["v","Вернуть копьем гори. И много душ",0,50,0,0],["v","Из-за меня на берегах погибло",0,51,0,0],["v","Кипучего Скамандра. Претерпев<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,52,0,0],["v","Все это зло, я остаюсь покрытой",0,53,0,0],["v","Проклятьями, и эллины твердят,",0,54,0,0],["v","Что я изменница, и в этой страшной",0,55,0,0],["v","Войне виновна.",0,55,0,0],["v","Для чего ж еще",1,55,0,0],["v","Живу я? Слово я храню от бога",0,56,0,0],["v","Гермеса: \"В Спарту с мужем ты вернешься;",0,57,0,0],["v","Узнает он, что не была ты в Трое,",0,58,0,0],["v","Не застилала ложа никому\".",0,59,0,0],["v","А здесь, пока на свет Протей глядел,",0,60,0,1],["v","За честь свою я не была в тревоге…",0,60,0,0],["v","Лишь с той поры, как мраком он одет",0,61,0,0],["v","Подземного селенья, сын Протея",0,62,0,0],["v","Меня на брак склоняет. Но супругу",0,63,0,0],["v","Я прежнему верна — и вот к могиле",0,63,0,0],["v","Протеевой с мольбой припала: пусть",0,64,0,0],["v","Покойный царь меня для мужа чистой,",0,65,0,0],["v","Как раньше, сохранит; и если имя",0,66,0,0],["v","В Элладе опорочено бесславьем",0,66,0,0],["v","Мое — хоть тела скверна не коснется!",0,67,0,0],["scene","Явление второе","s2",1,2],["sd","Со стороны моря приходит Тевкр. Он одет как путник: на голове шляпа, в руке лук. Все внимание его привлечено дворцом, и он не видит вначале <span class=\"ch\" data-ch=\"elena\">Елены</span>."],["sp","Тевкр"],["v","Вот дивная твердыня!.. Чья она?",0,68,0,0],["v","Для Плутоса б годилась… Стен высоких",0,69,0,0],["v","Венец державный — грозные зубцы…",0,70,0,1],["sd","(Переводит глаза на гробницу и с ужасом отступает, увидев <span class=\"ch\" data-ch=\"elena\">Елену</span>.)"],["v","Ба… ба…",0,70,0,0],["v","О боги! Что за вид ужасный! Образ",0,71,0,0],["v","Проклятой той, которая меня",0,72,0,0],["v","И Грецию сгубила…",0,72,0,0],["sd","(Обращаясь к <span class=\"ch\" data-ch=\"elena\">Елене</span>.)"],["v","Пусть бессмертным",0,73,4,0],["v","Настолько же ты будешь ненавистна,",0,74,0,0],["v","Насколько ты с <span class=\"ch\" data-ch=\"elena\">Еленой</span> схожа… Будь",0,75,0,0],["v","Не на чужой земле я, ты б пернатой",0,75,0,0],["v","Стрелы укусом искупила сладость,",0,76,0,0],["v","Что Зевсовой подобна дщери ты.",0,77,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","За что же эти громы? Сам-то кто,",0,77,0,0],["v","Несчастный, ты, и по какому праву",0,78,0,0],["v","Вина другой проклятья мне стяжала?",0,79,0,0],["sp","Тевкр"],["v","Я виноват… я гневу уступил…",0,80,0,1],["v","Элладе всей <span class=\"ch\" data-ch=\"elena\">Елена</span> ненавистна;",0,81,0,0],["v","Меня ж за речи извини, жена.",0,82,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но кто же ты? Откуда в этот край?",0,83,0,0],["sp","Тевкр"],["v","Ахеец я, один из этих горьких.",0,84,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Проклятиям <span class=\"ch\" data-ch=\"elena\">Елене</span> не дивлюсь;",0,85,0,0],["v","Но кто ты? Где отчизна? Кто отец?",0,86,0,0],["sp","Тевкр"],["v","По имени я — Тевкр; отцом слывет мне",0,87,0,0],["v","Царь Теламон, а Саламин — отчизной.<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,88,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А Нил тебе, его поля зачем?",0,89,0,0],["sp","Тевкр"],["v","Из отчего предела изгнан я.",0,90,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Несчастлив ты… Но кто ж тебя изгнал?",0,90,0,0],["sp","Тевкр"],["v","Заступник первый — Теламон-отец.",0,91,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","За что? Достойна слез судьба такая!",0,92,0,0],["sp","Тевкр"],["v","Аякса-брата смерть меня сгубила.",0,93,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но как? Ужели ты его убил?",0,94,0,0],["sp","Тевкр"],["v","Он добровольно пал на свой же меч.",0,95,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Сойдя с ума?.. Здоровый не дерзнет.",0,96,0,0],["sp","Тевкр"],["v","Пелея сыном был Ахилл, слыхала?",0,97,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Он сватался к <span class=\"ch\" data-ch=\"elena\">Елене</span>, говорят.<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,98,0,0],["sp","Тевкр"],["v","Убитый, он соратникам оставил",0,99,0,0],["v","Из-за своих доспехов тяжкий спор.",0,100,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но в чем же связь беды Аякса с этим?",0,101,0,0],["sp","Тевкр"],["v","Их взял другой, — Аякс не перенес.",0,102,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","И на тебя несчастье это пало?",0,103,0,0],["sp","Тевкр"],["v","За то, что с ним я вместе не погиб.",0,104,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","помолчав"],["v","Ты, значит, был под славным Илионом?",0,105,0,0],["sp","Тевкр"],["v","И сам себя сгубил с его стеной.",0,106,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","живо"],["v","Так Трои нет?.. Сожгли? Испепелили?",0,107,0,0],["sp","Тевкр"],["v","Не различить там даже места стен.",0,108,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Елена, горе! Ты сгубила Трою!",0,109,0,0],["sp","Тевкр"],["v","А с ней и нас. Какие реки крови!..",0,110,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Давно ли пал старинный Илион?",0,111,0,0],["sp","Тевкр"],["v","Семь раз с тех пор плоды с дерев снимали.",0,112,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А долго ли под Троей были вы?",0,113,0,0],["sp","Тевкр"],["v","Да, много лун за десять лет сменилось…",0,114,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А взяли вы… спартанскую жену?",0,115,0,0],["sp","Тевкр"],["v","Да, <span class=\"ch\" data-ch=\"menelay\">Менелай</span> — за косу золотую…<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,116,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","тонко усмехаясь"],["v","Ты видел сам бедняжку иль слыхал?",0,117,0,0],["sp","Тевкр"],["v","Как на тебя гляжу, ее я видел…",0,118,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Не боги ли играли вами, гость?",0,119,0,0],["sp","Тевкр"],["dir","угрюмо"],["v","Другую речь начни… об этом будет.",0,120,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","В своей догадке так уверен ты?",0,121,0,0],["sp","Тевкр"],["v","Глаза смотрели, да и ум мой зряч.",0,122,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Что ж? <span class=\"ch\" data-ch=\"menelay\">Менелай</span> с женой, поди уж, дома?",0,123,0,0],["sp","Тевкр"],["v","Их в Аргосе и на Евроте нет.",0,124,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","вздохнув"],["v","О, горе тем, о ком ты нам поведал…",0,125,0,0],["sp","Тевкр"],["v","Они пропали без вести — так молвят.",0,126,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но разве ж путь лежал ахейцам разный?",0,127,0,0],["sp","Тевкр"],["v","Один был путь… Да буря размела.",0,128,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А на каких водах случилась буря?",0,129,0,0],["sp","Тевкр"],["v","Эгейского с полморя мы прошли.",0,130,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","И с той поры его никто не видел?",0,130,0,0],["sp","Тевкр"],["v","Никто. Его в Элладе числят мертвым.",0,131,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","в сторону"],["sd","О, смерть моя!.. Дочь Фестия жива ль?"],["sp","Тевкр"],["v","Ты говоришь о Леде? Нет, скончалась.",0,132,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Не слава ли <span class=\"ch\" data-ch=\"elena\">Елены</span> тут виной?",0,133,0,0],["sp","Тевкр"],["v","Так говорят. На благородной шее<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,134,0,0],["v","Она стянула узел роковой.",0,135,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А Тиндариды живы иль не живы?",0,136,0,0],["sp","Тевкр"],["v","И живы и не живы; слух двоится.",0,137,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но что ж верней? О, горе мне, о, горе!",0,138,0,0],["sp","Тевкр"],["v","Есть слух такой, что звездами они",0,139,0,0],["v","Сияют нам с небес, богоподобны.",0,140,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, сладкие слова! Ну, а другой?",0,140,0,0],["sp","Тевкр"],["v","Из-за сестры как будто закололись.",0,141,0,0],["v","Однако не довольно ль? Оживлять",0,142,0,0],["v","Стенания — что пользы? Я хотел бы",0,143,0,0],["v","Здесь вещую увидеть: вот зачем",0,143,0,0],["v","До царской я твердыни добирался.",0,144,0,0],["v","Ты пособишь мне, может быть: из уст",0,145,0,0],["v","Горю узнать царевны <span class=\"ch\" data-ch=\"feonoya\">Феонои</span>,",0,146,0,0],["v","Куда крыло направить корабля",0,146,0,0],["v","От этих мест должны мы, чтобы Кипра",0,147,0,0],["v","Достичь верней: там Аполлон велел",0,148,0,0],["v","Нам обитать и город там назвать",0,149,0,0],["v","По имени родного Саламина.",0,150,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Тебя научит плаванье само.",0,150,0,0],["v","А этот край покинь, пока наследник",0,151,0,0],["v","Державного Протея, наш властитель,",0,152,0,0],["v","Тебя еще не видел: лов его",0,153,0,0],["v","Со сворами надежными сманил.",0,154,0,0],["v","Ему лишь в руки эллин попадется —",0,155,0,0],["v","Немедленно казнит. Из-за чего,",0,155,0,0],["v","Не спрашивай, пожалуйста: молчаньем",0,156,0,0],["v","Я связана, и пользы нет в словах.",0,157,0,0],["sp","Тевкр"],["v","Ты хорошо, жена, сказала; боги",0,158,0,0],["v","Пусть воздадут тебе за благо благом!",0,159,0,0],["v","Хоть видом ты похожа на <span class=\"ch\" data-ch=\"elena\">Елену</span>, —",0,160,0,1],["v","Душа иная у тебя — совсем",0,161,0,0],["v","Иная. Та пусть сгинет, светлых вод",0,162,0,0],["v","Еврота не увидев; а тебе",0,163,0,0],["v","Во всем, жена, успеха я желаю.",0,164,0,0],["sd","(Уходит обратно.)"],["scene","Вступительная песнь хора","s3",1,3],["sd","По уходе Тевкра <span class=\"ch\" data-ch=\"elena\">Елена</span> в грустном раздумье смотрит в сторону моря; во время следующей ее песни пятнадцать эллинских девушек, ее подруг, собираются вокруг нее."],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["sd","Тягостной скорби глубоко осевшие слезы… Какое Жалкому сердцу открылось ристалище стонов! Какая Песня вместит вас, — вы, слезы, вы, вопли, вы, муки?"],["str","Строфа I"],["v","Девы крылатые!",0,165,1,0],["v","Дети земли, сюда!",0,166,1,0],["v","Сюда, о сирены, на стон<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,167,1,0],["v","Песни надгробной, девы,",0,168,1,0],["v","С флейтой ли Ливии",0,170,1,1],["v","Иль со свирелью вы —",0,170,1,0],["v","Слезного дара жду",0,171,1,0],["v","Скорби взамен моей:",0,172,1,0],["v","Муку за муку мне,",0,173,1,0],["v","Песню за песню мне",0,173,1,0],["v","В сладком созвучии!",0,174,1,0],["v","Пусть Персефона примет от нас",0,175,0,0],["v","В темном чертоге своем",0,176,0,0],["v","Жертву рыданий для милых,",0,176,0,0],["v","Милых усопших.",0,177,1,0],["sp","Хор"],["str","Антистрофа I"],["v","Воды лазурные",0,178,1,0],["v","Взоры ласкали мне,",0,179,1,0],["v","Я же, лежа на нежной траве,",0,180,1,1],["v","Яркие ризы сушила,",0,180,1,0],["v","В блеске лучей золотых",0,181,1,0],["v","Солнца развесив их",0,182,1,0],["v","По тростникам младым.",0,183,1,0],["v","Жалобный боли крик",0,184,1,0],["v","Негу прервал мою:",0,185,1,0],["v","Стоны — не лиры звук:",0,185,1,0],["v","Нимфа-наяда так",0,186,1,0],["v","Стонет в горах, когда Пана насилье",0,187,0,0],["v","К браку неволит ее…",0,188,0,0],["v","Стонут за ней и утесы,",0,189,0,0],["v","Стонут ущелья.",0,190,1,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","простирая руки к женщинам"],["str","Строфа II"],["v","И<em>о</em>!.. И<em>о</em>!..",0,190,0,0],["v","Добыча диких скитальцев,<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,191,0,0],["v","Девы, девы Эллады…",0,192,0,0],["v","Моряк навестил нас ахейский",0,193,0,0],["v","Дар его — новые слезы:",0,194,0,0],["v","Пал Илион, и обломки",0,195,0,0],["v","Жаркое пламя пожрало…",0,196,0,0],["v","Тьмы я мужей сгубила…",0,197,0,0],["v","Их унесло <span class=\"ch\" data-ch=\"elena\">Елены</span>",0,198,0,0],["v","Полное муки имя.",0,199,0,0],["v","В петле вкусила Леда",0,200,0,1],["v","Смерть за мое бесславье;",0,200,0,0],["v","Долго носился по волнам",0,201,0,0],["v","Муж мой — и взят пучиной;",0,202,0,0],["v","Кастор и брат родимый",0,203,0,0],["v","Кастора, гордость и слава",0,204,0,0],["v","Родины нашей, — исчезли.",0,205,0,0],["v","Нет их на конном ристанье,",0,206,0,0],["v","Нет среди юношей стройных",0,207,0,0],["v","На состязанъях, на бреге",0,208,0,0],["v","Средь тростников высоких",0,209,0,0],["v","Пышнозеленых Еврота.",0,210,0,1],["sp","Хор"],["str","Антистрофа II"],["v","Увы! Увы!",0,210,4,0],["v","О, жребий долгого стона!",0,211,0,0],["v","Горькому демону, видно,",0,212,0,0],["v","В удел ты, жена, досталась",0,212,0,0],["v","В день, когда с думою лютой",0,213,0,0],["v","Зевс из эфирной сени",0,214,0,0],["v","К нежной Леде в объятья",0,215,0,0],["v","Лебедем белоснежным",0,215,0,0],["v","И влюбленным спускался!..",0,216,0,0],["v","Мука тебя какая,",0,217,0,0],["v","Мука, скажи, миновала?",0,217,0,0],["v","Чем не пытал тебя жребий?",0,218,0,0],["v","Матери нет на свете:",0,219,0,0],["v","Братьев уж нет под солнцем,",0,220,0,1],["v","Радость отчизны не светит",0,221,0,0],["v","Сердцу <span class=\"ch\" data-ch=\"elena\">Елены</span>, и ласкам",0,222,0,0],["v","Варвара злые толки",0,223,0,0],["v","Отдали грудь царицы.",0,224,0,0],["v","Муж твой погиб. Афины ж",0,225,0,0],["v","Медного дома больше",0,226,0,0],["v","В Спарте ты не увидишь.<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,227,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, увы! Увы! Увы!",0,230,0,1],["v","Под фригийской ли секирой",0,230,0,0],["v","Или эллинской упала",0,231,0,0],["v","Ель, в которой столько слез,",0,232,0,0],["v","Столько слез троянских было?",0,232,0,0],["v","Из нее ладью и весла",0,233,0,0],["v","Приамид себе устроил",0,234,0,0],["v","К очагу спартанца ехать",0,235,0,0],["v","За моею злополучной",0,235,0,0],["v","Красотой — для ласки брачной.",0,236,0,0],["v","О Киприда, о царица",0,237,0,0],["v","И обманов и убийства!",0,237,0,0],["v","Это ты хотела смерти",0,238,0,0],["v","Для данайцев и троян —",0,239,0,0],["v","Вот судьбы моей начало!",0,240,0,1],["v","Зевса строгая подруга",0,240,0,0],["v","Окрылила сына Майи",0,241,0,0],["v","Словом воли непреложной.",0,242,0,0],["v","И от луга, где, срывая",0,242,0,0],["v","Со стеблей живые розы,",0,243,0,0],["v","Наполняла я беспечно",0,244,0,0],["v","Ими пеплос, чтоб богине",0,244,0,0],["v","Посвятить их Меднозданной, —",0,245,0,0],["v","Неповинную <span class=\"ch\" data-ch=\"elena\">Елену</span>",0,246,0,0],["v","По стезе Гермес эфирной",0,246,0,0],["v","В этот грустный край уносит",0,247,0,0],["v","Для раздора, для раздора",0,248,0,0],["v","Меж Элладой и Приамом,",0,248,0,0],["v","Чтоб напрасные укоры",0,249,0,0],["v","На прибрежье Симоента",0,250,0,1],["v","Имя резали <span class=\"ch\" data-ch=\"elena\">Елены</span>!",0,251,0,0],["act","Действие первое","a2","I"],["scene","Явление третье","s4",2,4],["sd","<span class=\"ch\" data-ch=\"elena\">Елена</span> и хор."],["sp","Корифей"],["v","Ты в горе, знаю я; но все ж полезно<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,252,0,0],["v","Спокойней неизбежное нести.",0,253,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О жены, о подруги, что за рок",0,254,0,0],["v","Меня сковал? Иль я на свет родилась",0,255,0,0],["v","Чудовищем, загадкой? Так во мне<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,256,0,1],["v","Все странно, необычно так… То Геры",0,260,0,1],["v","Игрушкой становлюсь я, то своей",0,260,0,0],["v","Красы безвольной жертвой… Боги, боги!",0,261,0,0],["v","Стираются же краски и со статуй;",0,262,0,0],["v","Так отчего ж мою вы красоту",0,263,0,0],["v","Не смените первичным безобразьем?",0,263,0,0],["v","Тогда б забыли греки тот позор,",0,264,0,0],["v","Который нам навязан, и хвалила",0,265,0,0],["v","Меня молва, та, что так зло теперь",0,266,0,0],["v","<span class=\"ch\" data-ch=\"elena\">Елены</span> имя треплет.",0,266,0,0],["v","Тяжко людям,",1,266,0,0],["v","Коль боги им испортят жизнь одним",0,267,0,0],["v","Каким-нибудь несчастьем; но смириться",0,268,0,0],["v","Все ж легче им… Меня со всех сторон",0,269,0,0],["v","Несчастья оцепили. Клеветою",0,270,0,1],["v","Опутана <span class=\"ch\" data-ch=\"elena\">Елена</span>; а куда ж",0,270,0,0],["v","Безвинные заслуженных тяжеле",0,271,0,0],["v","Страдания! Из родины меня",0,272,0,0],["v","В край варварский перенесли владыки",0,273,0,0],["v","Судьбы моей; лишенная семьи,",0,273,0,0],["v","Рабой царевна стала. Все — рабы ведь<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,274,0,0],["v","У варваров; свободен — лишь один.",0,275,0,0],["v","А якорь тот — единственный, который",0,276,0,0],["v","Еще держал ладью моей судьбы, —",0,276,0,0],["v","Надежда, что за мной Атрид приедет",0,277,0,0],["v","И вызволит из горестей меня, —",0,278,0,0],["v","Его уж нет: в волнах погиб мой муж.",0,279,0,0],["v","И мать погибла, и ее убийцей",0,280,0,1],["v","Считаюсь я. Неправдой, пусть; но все же",0,280,0,0],["v","Неправда та — моя. Краса хором,",0,281,0,0],["v","В девичестве седеет Гермиона…",0,282,0,0],["v","И даже тех, которым имя дал",0,283,0,0],["v","Отец их Зевс, — моих не стало братьев…",0,283,0,0],["v","И вот в пучине неустанных бед",0,284,0,0],["v","Страданьем, недеяньем сражена я.",0,285,0,0],["v","И в довершенье если бы в отчизну",0,286,0,0],["v","И удалось вернуться — предо мной",0,286,0,0],["v","Она б закрыла двери: за <span class=\"ch\" data-ch=\"elena\">Елену</span>",0,287,0,0],["v","Троянскую там приняли б меня,",0,288,0,0],["v","За ту, что с <span class=\"ch\" data-ch=\"menelay\">Менелаем</span> возвращалась.",0,289,0,0],["v","Будь жив еще Атрид, друг друга мы",0,290,0,1],["v","Узнали бы — приметы есть такие,",0,290,0,0],["v","Что их никто не знает. Но его",0,291,0,0],["v","Уж нет, и нет спасенья.",0,292,0,0],["v","Жизнь зачем же,",1,292,0,0],["v","Скажите мне, еще? Какой удел",0,293,0,0],["v","Готовлю я себе? Чертог богатый",0,294,0,0],["v","У варвара супруга и его",0,295,0,0],["v","Обильный стол? Но если телом мужу",0,295,0,0],["v","Отдастся ненавистному супруга —",0,296,0,0],["v","И тело ненавистным станет ей.",0,297,0,0],["v","Нет, лучше смерть… но только бы покраше.",0,298,0,0],["v","Висячей петли безобразен вид;",0,299,0,0],["v","Рабам и тем позор! В мече, напротив,",0,300,0,1],["v","Есть что-то благородное. К тому ж",0,301,0,0],["v","Одной минуты дело… Вот какая",0,302,0,0],["v","Пучина зол вокруг!.. Других краса",0,303,0,0],["v","Венчает счастьем — мне она в погибель.",0,304,0,0],["sp","Корифей"],["v","Кто б ни был гость, — должна ли всем словам",0,305,0,0],["v","Пришельца ты давать, царица, веру?",0,306,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Он говорил о муже слишком ясно.",0,307,0,0],["sp","Корифей"],["v","Бывает ясен часто лживый сказ!",0,308,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да, но правдивый — и того яснее!",0,310,0,1],["sp","Корифей"],["v","Там зло, здесь благо; зло ль тебе милее?",0,311,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","В сетях тревоги всюду вижу страх.",0,312,0,0],["sp","Корифей"],["v","Скажи: в дворце-то ласковы с тобою?",0,313,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Милы мне все; жених лишь ненавистен.",0,314,0,0],["sp","Корифей"],["v","Ты вот что сделай: памятник покинув…",0,315,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А дальше что ж? Какой совет услышу?",0,316,0,0],["sp","Корифей"],["v","В чертог войди. Там Нереиды дочь,",0,317,0,0],["v","Которой все открыто, Феоноя,",0,318,0,0],["v","Пусть возвестит тебе, в живых ли муж",0,320,0,1],["v","Иль умер. И тогда увидишь, стоны ль",0,320,0,0],["v","Твоей судьбе приличны или радость.",0,321,0,0],["v","А не узнав наверное, тебе",0,322,0,0],["v","Какая ж польза плакать?",0,323,0,0],["sd","(Видя, что <span class=\"ch\" data-ch=\"elena\">Елена</span> колеблется.)"],["v","Ну, исполни ж",0,323,4,0],["v","Мои слова, <span class=\"ch\" data-ch=\"elena\">Елена</span>: брось гробницу",0,324,0,0],["v","И вопроси царевну. Под рукой",0,325,0,0],["v","Разгадки ключ: зачем же ждать чего-то",0,326,0,0],["v","И впереди искать? И я с тобой",0,326,0,0],["v","Охотно в дом войду, чтоб девы вещей",0,327,0,0],["v","Гадания услышать. Не жене ль",0,328,0,0],["v","С женой делить ее труды и муки?",0,329,0,0],["sd","<span class=\"ch\" data-ch=\"elena\">Елена</span> после некоторого колебания соглашается; хор собирается вокруг нее. Движения эти сопровождаются музыкой."],["scene","Сцена плача","s5",2,5],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Совет ваш, он сердцу мил;",0,330,0,1],["v","Идите ж, идите в чертог,",0,330,0,0],["v","Подруги, узнайте мук",0,331,0,0],["v","Исход и борьбы моей.",0,332,0,0],["sp","Хор"],["v","Желанья мои с тобой.",0,333,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О ты, злополучный день!",0,334,0,0],["v","Какую я весть услышу,",0,335,0,0],["v","Каким ее плачем встречу?",0,336,0,0],["sp","Хор"],["v","Беды не накличь себе!",0,337,0,0],["v","Стенаньем до времени",0,338,0,0],["v","Не мучь себе сердца ты!",0,339,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Что сталось с супругом моим?",0,340,0,1],["v","Видит ли свет",0,340,0,0],["v","И колесницу солнца,",0,341,0,0],["v","И в небе светил дороги?",0,342,0,0],["v","Иль под землей меж мертвых",0,343,0,0],["v","Ночи приял покров он?",0,344,0,0],["sp","Хор"],["v","В мыслях лелей — что краше…",0,345,0,0],["v","Дальше там будь что будет!",0,346,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Тебя призываю я с клятвой,",0,347,0,0],["v","Тебя, в тростниках зеленых,",0,348,0,0],["v","Еврот мой студеноструйный:",0,349,0,0],["v","Если верна та слава,",0,350,0,1],["v","Слава о смерти мужа…",0,350,0,0],["sp","Хор"],["v","Ты теряешь рассудок!",0,351,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","В петле тогда воздушной",0,352,0,0],["v","На смерть укачаю тело,",0,353,0,0],["v","Или, булатною силой",0,353,0,0],["v","Души сокрушив покровы,",0,354,0,0],["v","Груди пронзенной влагой",0,355,0,0],["v","Губительный меч оболью;",0,356,0,0],["v","Жертвой паду трех богинь,",0,356,0,0],["v","Жертвой того Приамида,",0,357,0,0],["v","Что их в ущелье идейском",0,358,0,0],["v","Ждал у загонов своих.",0,359,0,0],["sp","Хор"],["v","Пусть на других падают беды!",0,360,0,1],["v","Ты же счастлива будешь.",0,360,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О город бед, о Троя!",0,361,3,0],["v","Деяний несодеянных",0,362,3,0],["v","Тебя мечта сгубила,",0,362,3,0],["v","И ты познала муки!",0,363,3,0],["v","Красота моя — Кипридин",0,364,3,0],["v","Дар — ценою слез и крови",0,364,3,0],["v","Окупилась: беды к бедам,",0,365,3,0],["v","Слезы к слезам, муки к мукам.",0,366,3,0],["v","Мать детей своих оплачет,",0,366,3,0],["v","Сестры волосы обрежут",0,367,3,0],["v","В слезный дар погибшим братьям",0,368,3,0],["v","Там, у темных вод Скамандра…",0,368,3,0],["v","И смешался крик со стоном",0,369,3,0],["v","В городах Эллады; руки",0,370,3,1],["v","На главу кладут там жены,",0,371,3,0],["v","Ногти жадные вонзают",0,372,3,0],["v","Девы в нежные ланиты.",0,373,3,0],["v","О Каллисто, ты блаженна, Аркадии дочь!<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,374,0,0],["v","Пусть даже бога любовь тебя в зверя тогда обратила,",0,375,0,0],["v","Все же твой жребий завиднее жребия Леды.",0,376,0,0],["v","В шерсти мохнатой, с глазами, горящими яро,",0,377,0,0],["v","Ты избежала сознания муки…",0,380,0,1],["v","Счастлива ты, Титанида, Меропова дщерь!",0,380,0,0],["v","Дивно красивая стала оленем с златыми рогами…",0,381,0,0],["v","И избежала стрелы Артемиды.",0,382,0,0],["v","Ты же, краса моя, ты",0,383,3,0],["v","Башни сгубила Приама,<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a><a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,384,3,0],["v","Лучших ахейцев сгубила!",0,385,3,0],["sd","Уходит в ворота с хором. Видно, как они все поднимаются по откосу кремля. У дверей дворца их встречает старая привратница; узнав их, она их впускает и закрывает за ними двери. Сцена остается пустой, музыка умолкает."],["scene","Явление четвертое","s6",2,6],["sd","Со стороны моря приходит <span class=\"ch\" data-ch=\"menelay\">Менелай</span>. Его одежда в беспорядке и носит следы кораблекрушения, волосы и борода не расчесаны. Из-под лохмотьев виднеется, однако, большой меч. Он без свиты."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О царь Пелоп, когда-то на полях",0,386,0,0],["v","Писийских колесницу Эномая",0,387,0,0],["v","Опередивший, о, зачем, скажи,",0,388,0,0],["v","Тогда среди богов ты не почил,",0,389,0,0],["v","Когда еще отцом Атрея не был,",0,390,0,1],["v","Родившего от Аэропы нас",0,390,0,0],["v","С Агамемноном-братом, двух героев?",0,391,0,0],["v","Без похвальбы сказать могу: в таком",0,392,0,0],["v","Числе еще не видел мир и войска,",0,393,0,0],["v","В каком я вел на кораблях ахейцев",0,394,0,0],["v","Под Илион. Им не навязан был я,<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,395,0,0],["v","Я выбором гордиться молодежи",0,395,0,0],["v","Могу как вождь.",0,396,0,0],["v","И что ж? Одних уж нет,",1,396,0,0],["v","Другие же, пощажены волною,",0,397,0,0],["v","Одно несут — умерших имена",0,398,0,0],["v","В далекую отчизну. По лазурным",0,399,0,0],["v","Морским волнам и сам я с той поры,",0,400,0,1],["v","Как башни Трои рушил, бесприютен",0,400,0,0],["v","Скитаюсь столько лет — хоть поглядеть",0,401,0,0],["v","На Спарту бы… Но богу не угодно…",0,402,0,0],["v","Я Ливии оплавал берега:",0,403,0,0],["v","Суровы и пустынны. А к Элладе",0,403,0,0],["v","Едва меня приблизят волны, тотчас",0,404,0,0],["v","Назад уносит судно ветер — мне",0,405,0,0],["v","Попутного не посылали боги",0,406,0,0],["v","В Лакедемон родимый…",0,406,0,0],["v","Потерпел",1,406,0,0],["v","Я только что крушенье; я лишился",0,407,0,0],["v","Товарищей и выброшен на берег",0,408,0,0],["v","Из корабля, который на куски",0,409,0,0],["v","Разбился о скалу. От хитрых снастей",0,410,0,1],["v","Остался только киль: едва-едва,",0,410,0,0],["v","Не чая и спасения, на киле",0,411,0,0],["v","До суши я добрался и жену",0,412,0,0],["v","Привез на нем, отбитую под Троей…",0,413,0,0],["v","Названия народа и страны",0,414,0,0],["v","Не знаю я, толпы же стыдно; будут",0,415,0,0],["v","Расспрашивать, а я… во что одет?",0,415,0,0],["v","Ведь, если кто поставлен был высоко",0,416,0,0],["v","И в нищету впадает, — тяжелей",0,417,0,0],["v","Ему его страдание бывает,",0,418,0,0],["v","Чем искони несчастному. Нужда",0,419,0,0],["v","Вконец меня терзает: хлеба нету",0,420,0,1],["v","И не во что одеться. Нагота",0,420,0,0],["v","Едва прикрыта моря изверженьем,",0,421,0,0],["v","А пеплосы, блестящие плащи,",0,422,0,0],["v","Всю роскошь одеяний волны скрыли.",0,423,0,0],["v","Виновница несчастья моего",0,424,0,0],["v","Запрятана в пещеры недра; ложе",0,425,0,0],["v","Мое там охраняют из друзей",0,426,0,0],["v","Последние спасенные; а сам я",0,427,0,0],["v","Отправился на поиски один,",0,428,0,0],["v","Не выгляжу ль поживы… Вот палаты",0,429,0,0],["v","Державные с зубцами и ворота",0,430,0,1],["v","Дубовые; заметно по всему,",0,430,0,0],["v","Что богачи живут… Ну что ж! Волнами",0,431,0,0],["v","Разбитому богатый дом в куске",0,432,0,0],["v","Уж не откажет: а бедняк — хотя бы",0,433,0,0],["v","Он и желал — не в силах нам помочь.",0,434,0,0],["sd","(Входит в ворота, поднимается по откосу кремля и стучится в запертую дверь дворца.)"],["scene","Явление пятое","s7",2,7],["sd","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> и привратница <span class=\"ch\" data-ch=\"feonoya\">Феонои</span> (приоткрывает дверь; увидев чужестранца, она быстро становится перед ней и поднимает руку в знак отказа)."],["v","Гей, там, послушай! Гей, привратник! Ближе!",0,435,0,0],["v","Прими рассказ печали для господ!",0,436,0,0],["sp","Привратница"],["dir","угрюмо"],["v","Кто там?.. Нельзя ль подальше от дверей?",0,437,0,0],["v","Оставишь ли хозяина тревожить?..",0,438,0,0],["v","Не то — смотри! Ты грек… Так из чертога",0,439,0,0],["v","Уйдешь ли цел ты? Им приема нет.",0,440,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Спасибо за совет, старуха; медлить",0,441,0,0],["v","Не буду я; да ласковей нельзя ль?",0,442,0,0],["sp","Привратница"],["dir","с угрожающим жестом"],["v","Ступай, ступай! Мне велено, пришелец,",0,443,0,0],["v","Чтоб за порог ахейцев ни души…",0,444,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Выталкивать зачем же? Что за строгость!",0,445,0,0],["sp","Привратница"],["v","Сам виноват… Кому я говорю?",0,446,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ты доложи хозяевам о нас-то.",0,447,0,0],["sp","Привратница"],["v","Докладу сам не будешь рад, поверь!",0,448,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Спасенный богом, я священен вам!",0,449,0,0],["sp","Привратница"],["v","Других учи, а тут не достучишься.",0,450,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Сюда войду… И лучше ты не спорь…",0,451,0,0],["sp","Привратница"],["v","Назойливый! Ты будешь силой выгнан!",0,452,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","в сторону"],["v","Увы! Увы! Дружина… цвет дружин!",0,453,0,0],["sp","Привратница"],["v","Там был в чести ты, знать; а здесь — ничто.",0,454,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","сквозь слезы"],["v","О демон мой! За что меня бесчестишь?",0,455,0,0],["sp","Привратница"],["dir","несколько смягчившись"],["v","А слезы-то зачем и столько стонов?",0,456,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О счастии припомнил я былом.",0,457,0,0],["sp","Привратница"],["v","О нем иди перед друзьями плакать.",0,458,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да где же я и чей чертог блюдешь ты?",0,459,0,0],["sp","Привратница"],["v","В Египте ты и дом Протея видишь.",0,460,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","В Египте? О, куда я занесен?",0,461,0,0],["sp","Привратница"],["v","За что ж хулить святую влагу Нила?",0,462,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Хула не ей, а сонму бед моих.",0,463,0,0],["sp","Привратница"],["v","Не ты один, несчастных всюду много.",0,464,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Был назван царь… а где же он сейчас?",0,465,0,0],["sp","Привратница"],["v","Вот гроб его… А правит сын Протея.",0,466,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","В отъезде ли иль дома он теперь?",0,467,0,0],["sp","Привратница"],["v","В отъезде, да… Ахейцам враг он лютый.",0,468,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А в чем причина? Ведь не я виновен!",0,469,0,0],["sp","Привратница"],["v","Елена, Зевса дочь, в чертоге этом.",0,470,0,1],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","подходит к старухе и касается ее руки. Тревожно"],["v","Как?.. Повтори, жена… что ты сказала?",0,470,0,0],["sp","Привратница"],["v","Тиндара дочь, спартанка, здесь живет.",0,471,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","с возрастающей тревогой"],["v","<span class=\"ch\" data-ch=\"elena\">Елена</span>?! Нет… Откуда?.. В чем тут дело?",0,472,0,0],["sp","Привратница"],["v","Из Лакед<em>е</em>мона сюда пришла.",0,473,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Постой… Давно? (Про себя.) Украли из пещеры?..",0,474,0,0],["sp","Привратница"],["v","Под Трою грек еще не уплывал.",0,475,0,0],["v","Но удались от дома. Есть помеха",0,476,0,0],["v","Особая теперь, и царский дом",0,477,0,0],["v","В смятенье весь. Не в добрый час ты прибыл.",0,478,0,0],["v","Застань тебя хозяин, он казнит",0,479,0,0],["v","Пришельца вместо дара. Я душою",0,480,0,1],["v","За эллинов, и только страх господ",0,480,0,0],["v","Меня к словам таким склоняет горьким.",0,481,0,0],["sd","(Уходит и затворяет дверь.)"],["sd","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> отходит от дома в раздумье и спускается обратно на площадку."],["scene","Явление шестое","s8",2,8],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","один"],["v","Что тут сказать? Придумать что? Еще ль",0,482,0,0],["v","Несчастий не довольно? Мне о новом",0,483,0,0],["v","Здесь говорят. Жену, с таким трудом",0,484,0,0],["v","Добытую, я поручаю страже…",0,485,0,0],["v","И что ж? Ее прозванием себя",0,486,0,0],["v","Другая именует, в этом царском",0,487,0,0],["v","Дворце живет… Нет, дочерью она",0,488,0,0],["v","Ее назвала Зевса… Или Зевсом",0,489,0,0],["v","Зовут кого на Ниле? Ведь один",0,490,0,1],["v","На небесах Зевес. И Спарты нету,",0,490,0,0],["v","Помимо той, которую Еврот,",0,491,0,0],["v","Средь тростников сверкающий, прославил.",0,492,0,0],["v","Тиндарово не двое ль имя носят?",0,493,0,0],["v","Не два ли есть Лакедемона? Трои",0,494,0,0],["v","Не две ли уж? Ума не приложу…",0,495,0,0],["v","Положим, есть среди земель обилья",0,496,0,0],["v","И города и жены, что одним",0,497,0,0],["v","Прозванием гордятся… В этом дива",0,498,0,0],["v","Никто не видит даже.",0,499,0,0],["v","А угроз",1,499,0,0],["v","Служанки мне едва ль бояться можно;",0,500,0,1],["v","Жестокого такого сердца нет,",0,500,0,0],["v","Чтоб отказать в куске пришельцу, имя",0,501,0,0],["v","Назвавшему Атрида… Далеко ведь",0,502,0,0],["v","Сверкает Трои пламя, и герой,",0,503,0,0],["v","Его зажегший, Менелай, повсюду",0,504,0,0],["v","Прославлен на земле. Нет, я дождусь",0,505,0,0],["v","Хозяина. А дальше два исхода:",0,505,0,0],["v","Коли душой он варвар, проберусь",0,506,0,0],["v","Обратно я к обломкам; если ж сердце",0,507,0,0],["v","Смягчить его сумею, не откажет",0,508,0,0],["v","Он нам помочь в несчастии…",0,509,0,0],["v","Нет горше,",1,509,0,0],["v","Как умолять царей о подаянье,",0,510,0,1],["v","Когда царем ты сам рожден; но что ж",0,510,0,0],["v","Поделаешь? Нужда!.. Не я придумал,",0,511,0,0],["v","А мудрые сложили, что сильней",0,512,0,0],["v","Нет ничего нужды суровой в мире.",0,513,0,0],["scene","Вторая вступительная песнь хора","s9",2,9],["sd","Хор и <span class=\"ch\" data-ch=\"elena\">Елена</span> выходят радостные и оживленные из дверей. Все они спускаются на площадку."],["sp","Хор"],["v","Вещей внимала я деве",0,514,0,0],["v","Там, у царей в чертоге…",0,515,0,0],["v","Дева сказала, что царь <span class=\"ch\" data-ch=\"menelay\">Менелай</span>",0,516,0,0],["v","В черный Эреб",0,517,0,0],["v","Еще не спускался,",0,518,0,0],["v","Землею еще не покрыт он,",0,519,0,0],["v","Пучина еще морская",0,520,0,1],["v","Носит царя, и силы",0,520,0,0],["v","Горький теряет, родных",0,521,0,0],["v","Берегов коснуться не может",0,522,0,0],["v","В печальной доле скитальца…",0,523,0,0],["v","Нет у него друга, земель же",0,524,0,0],["v","Каких он, каких в скитанье",0,525,0,0],["v","Веслом не задел, злополучный,",0,525,0,0],["v","С тех пор, как оставил Трою!",0,526,0,0],["act","Действие второе","a3","II"],["scene","Явление седьмое","s10",3,10],["sd","Елена, отделившись от хора, направляется к ступеням, ведущим на курган. <span class=\"ch\" data-ch=\"menelay\">Менелая</span> она не видит: их разделяет гробница."],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","в радостном раздумье"],["v","Протеева могила, ты опять",0,527,0,0],["v","Меня прими… А вести <span class=\"ch\" data-ch=\"feonoya\">Феонои</span>",0,528,0,0],["v","Отрадно прозучали: все она,",0,529,0,0],["v","Все, вещая, проникла: <span class=\"ch\" data-ch=\"menelay\">Менелай</span>",0,530,0,1],["v","Еще глядит на солнце; море горьким",0,530,0,0],["v","Исчерчено в бесчисленных путях,",0,531,0,0],["v","И, жребием скитальческим носимый,",0,532,0,0],["v","Он столько видел бед!.. Придет же он,",0,533,0,0],["v","Когда конец страданиям наступит.",0,534,0,0],["v","Лишь одного не досказала: жив ли",0,535,0,0],["v","Останется, придя ко мне; спросить",0,535,0,0],["v","Не домекнулась: так отрадно было",0,536,0,0],["v","Узнать, что жив еще. Твердила дева",0,537,0,0],["v","Еще, что он крушенье потерпел,",0,538,0,0],["v","Поблизости как будто, и немногих",0,539,0,0],["v","С собою спас… О, скоро ль ты, желанный?",0,540,0,1],["sd","(Замечает <span class=\"ch\" data-ch=\"menelay\">Менелая</span> и останавливается в страхе и нерешительности.)"],["sd","<span class=\"ch\" data-ch=\"menelay\">Менелай</span> выходит из-за гробницы и хочет пересечь ей дорогу, не давая ей дойти до нее."],["v","Ба… это кто ж? Не козни ль строит нам",0,540,0,0],["v","Протеев сын безбожный? Шибче лани",0,541,0,0],["v","Иль одержимой богом долечу",0,542,0,0],["v","Я до могилы… Сестры! Как он страшен!",0,543,0,0],["v","Схватить меня он хочет… О, скорей…",0,544,0,0],["sd","(Бежит.)"],["sd","Менелай, не касаясь ее, заграждает ей путь. <span class=\"ch\" data-ch=\"elena\">Елена</span> принуждена остановиться."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Отчаянный и быстрый этот бег",0,545,0,0],["v","К стенам гробницы, черным от огня,",0,546,0,0],["v","Останови, молю… Спешишь зачем?",0,547,0,0],["v","О женщина, твой образ наполняет",0,548,0,0],["v","Мне сердце ужасом — язык коснеет…",0,549,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","пользуется минутой замешательства, чтобы пройти к гробнице, но <span class=\"ch\" data-ch=\"menelay\">Менелай</span> продолжает стоять мрачной угрозой, хотя по-прежнему не делает движений, чтобы задерживать <span class=\"ch\" data-ch=\"elena\">Елену</span>"],["v","О жены! Помогите! Не пускает",0,550,0,1],["v","Нас этот муж к могиле… Женихом",0,551,0,0],["v","Подослан ненавистным он за мною…",0,552,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Нет, я не вор и злому не слуга…",0,553,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но посмотри, как ты одет… во что…",0,554,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","простирая молящие руки"],["v","Не бойся же меня: остановись!",0,555,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","которую <span class=\"ch\" data-ch=\"menelay\">Менелай</span> пустил на ее место, теперь пристально всматривается в собеседника. <span class=\"ch\" data-ch=\"menelay\">Менелай</span>, который обратился к ней лицом, тоже всматривается в <span class=\"ch\" data-ch=\"elena\">Елену</span>"],["sd","Пауза."],["v","Могилы я коснулась и стою…",0,556,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Кто ты, скажи? Кого я вижу, боги?",0,557,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Открой себя. Желанья нас роднят.",0,558,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","как бы про себя"],["v","Такого я еще не видел сходства.",0,559,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Мой бог!.. Ведь бог — узнание друзей!",0,560,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","не сводя глаз с <span class=\"ch\" data-ch=\"elena\">Елены</span>"],["v","Гречанка ты иль здешняя? Скажи мне.",0,560,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Гречанка, да… А ты? Ты тоже грек?",0,561,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ты до того похожа на <span class=\"ch\" data-ch=\"elena\">Елену</span>.",0,562,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ты ж — вылитый Атрид… Нет слов сказать…",0,563,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, это я — увы! — несчастный этот.",0,564,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","делает порывистое движение, чтобы его обнять"],["v","О, наконец вернулся ты к жене!",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","разводя ее руки, видимо борясь с собой"],["v","К жене?.. Оставь… ко мне не прикасайся!",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Отец Тиндар нас обручил… Ты мой…",0,566,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Светоченосная Геката! Призрак",0,567,0,0],["v","Да будет благ, что мне прислала ты!",0,568,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Опомнись! Страшной Деве перекрестков",0,569,0,0],["v","Я не служу, и день кругом, не ночь.",0,570,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но я — один: не двух же жен я муж!",0,571,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Двух жен?.. Но кто ж она, жена другая?",0,572,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Под Троей взял и в гроте берегу.",0,573,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","уверенно и твердо"],["v","Нет у тебя второй жены <span class=\"ch\" data-ch=\"elena\">Елены</span>.",0,574,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","всматриваясь в <span class=\"ch\" data-ch=\"elena\">Елену</span>"],["v","Иль цел мой ум, но лгут мои глаза?",0,575,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Неужто ж ты жены узнать не можешь?",0,576,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","стараясь придать голосу твердость"],["v","Да, сходство есть… Но убежденья нет.",0,577,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Глаза открой… Поруки нет вернее.",0,578,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Бесспорно, ты похожа на нее.",0,579,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Кому ж, скажи, коль не глазам, и верить?",0,580,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но как же я поверю… при другой?",0,581,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Там, в Трое, был мой призрак, не сама я.",0,582,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но кто же создает тела живые?",0,583,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Эфир… Тот призрак соткан из него.",0,584,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но кто же ткач? Невероятен сказ твой.",0,585,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Кто? Гера — чтоб не взял меня Парис.",0,586,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","усмехаясь"],["v","Что ж, ты зараз и здесь и там была?",0,587,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Бывает имя всюду, тело — нет.",0,588,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","мрачно"],["v","Оставь! И так на сердце много горя.",0,589,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","с дрожью в голосе"],["v","Меня ты бросишь, тень возьмешь с собой?",0,590,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Дай боже благ тебе за сходство с нею!",0,590,0,0],["sd","(Делает несколько шагов от алтаря.)"],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","ломая руки"],["v","О, смерть! Нашла — и вновь теряю мужа!",0,591,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","останавливаясь, твердо"],["v","Не прогневись: трудов своих обузе",0,592,0,0],["v","Я верю больше, чем тебе, жена.",0,593,0,0],["sd","(Хочет уйти.)"],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","с отчаянием в голосе"],["v","О, есть ли кто несчастнее меня!",0,594,0,0],["v","Вернейший друг бросает. Он надежду",0,595,0,0],["v","Увидеть дом, Элладу — все унес…",0,596,0,0],["sd","(Закрывает лицо руками.)"],["scene","Явление восьмое","s11",3,11],["sd","Те же и старый слуга <span class=\"ch\" data-ch=\"menelay\">Менелая</span> со стороны моря — оборванный, обветренный, без шапки; спутанные волосы и грубые, красные руки гребца."],["sp","Слуга"],["dir","почти натыкаясь на <span class=\"ch\" data-ch=\"menelay\">Менелая</span>"],["v","О Менелай!.. Насилу-то сыскал я",0,597,0,0],["v","Тебя, о царь: изрыскал всю страну.",0,598,0,0],["v","Товарищи меня к тебе послали.",0,599,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","останавливаясь"],["v","Не варвар ли ограбил вас, гонец?",0,600,0,1],["sp","Слуга"],["v","Нет, чудеса случились… Да такие,",0,600,0,0],["v","Что и в словах-то их не уместишь…",0,601,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ты так спешишь, что, верно, вести важны.",0,602,0,0],["sp","Слуга"],["dir","быстро, но не без расчета на эффект"],["v","Царь… Сколько мук подъял ты… А за что?",0,602,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","несколько утомленным тоном"],["v","Они прошли… Ты ж новости имеешь?",0,603,0,0],["sp","Слуга"],["dir","продолжая в том же тоне"],["v","Твоей жены нет больше… Поднялась",0,604,0,0],["v","В эфир она…",0,605,0,0],["v","<span class=\"ch\" data-ch=\"elena\">Елена</span> жадно прислушивается.",0,605,0,0],["v","Исчезла; небо скрыло",0,606,4,0],["v","Ее от глаз, и сторожить остались",0,607,1,0],["v","Пещеру мы пустую. Вот слова",0,607,1,0],["v","Последние ее: \"Несчастны вы,",0,608,1,0],["v","Фригийцы, эллины! Из-за меня вы",0,609,1,0],["v","В Скамандровой долине полегли",0,610,1,1],["v","По Геры замыслу: вам всем казалось,",0,610,1,0],["v","Что Александр владел <span class=\"ch\" data-ch=\"elena\">Еленой</span> — ею",0,611,1,0],["v","Он не владел. А я, исполнив срок",0,612,1,0],["v","И соблюдя веленье Мойры, снова",0,613,1,0],["v","К отцу Эфиру возвращаюсь. Жаль",0,613,1,0],["v","Мне Тиндариду, что с душой невинной",0,614,1,0],["v","Молвою опорочена она!\"",0,615,1,0],["sd","(Быстро поворачивается и, встретившись глазами с напряженно слушающею его <span class=\"ch\" data-ch=\"elena\">Еленой</span>, тотчас ее узнает. Никаких сомнений для него нет. В его обращении к ней почтительность приправлена досадой.)"],["v","Привет тебе, о Леды дочь! Так вот где",0,616,1,0],["v","Открылась ты — а я-то доношу,",0,616,1,0],["v","Что в звездный мир от нас ты удалилась,",0,617,1,0],["v","Не догадавшись, что крылатым телом",0,618,1,0],["v","Владеешь ты. Не попрекай же нас",0,619,1,0],["v","Вторично, что напрасно мы трудились —",0,620,1,1],["v","И муж и рать — под Троей за тебя!",0,620,1,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Я понял все… Ее слова сошлись<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,621,0,0],["v","С рассказом этим.",0,622,0,0],["sd","(Расцветая улыбкой и будто помолодев даже, направляется к <span class=\"ch\" data-ch=\"elena\">Елене</span>.)"],["v","О желанный день!",0,623,4,0],["v","Объятьям ты вернул мою <span class=\"ch\" data-ch=\"elena\">Елену</span>!",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","порывисто обнимая его"],["v","О Менелай… Любимый… Годы мук",0,624,0,0],["v","В какую даль ушли… а наслажденье",0,625,0,0],["v","Так свеже… О подруги! Он со мной.",0,626,0,0],["v","Девушки обступают <span class=\"ch\" data-ch=\"elena\">Елену</span>. Музыка.",0,626,0,0],["v","Я нашла его: какая радость!",0,627,0,0],["v","Я его, лаская, обнимаю…",0,628,0,0],["v","Сколько дней, о милый, сколько дней!..",0,629,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","отвечая объятиям"],["v","Да, ты моя! Так много на губах",0,630,0,1],["v","Вопросов и рассказов… Как начну я?..",0,631,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Я дрожу от радости. Желанья",0,632,0,0],["v","Волосы на голове вздымают,",0,633,0,0],["v","И к тебе я крепко прижимаюсь.",0,634,0,0],["v","Ты мой муж, мой муж, моя отрада!",0,635,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Как сладко мне в глаза твои глядеть!",0,636,0,0],["v","На жребий не сержусь я больше, нет.",0,637,0,0],["v","Да, это дочь Кронида, Леды дочь;",0,638,0,0],["v","Ей, ей чета блаженных белоконных<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,640,0,1],["v","С приветным кликом светочи несла!",0,640,0,0],["v","Ах, бог супругу разлучил со мною,",0,641,0,0],["v","Судьбу судил иную ей — и воля",0,642,0,0],["v","Свершилась необорная его;",0,643,0,0],["v","С недолей доля вновь соединила",0,643,0,0],["v","С тобой меня; мы встретились — хоть отдых…",0,644,0,0],["v","О, счастье! Все ж не покидай меня!<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,645,0,0],["sp","Корифей"],["v","Будь счастлив, гость! Богов молю о том же:",0,646,0,0],["v","Одна судьба, одно у вас и счастье.",0,646,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","хору"],["v","Подруги мои!",0,647,0,0],["v","Стоны мои умолкли. Ни слова",0,648,0,0],["v","Больше о прошлых страданьях.",0,649,0,0],["v","Вот он, которого сердце биением каждым",0,650,0,1],["v","Ждало так долго, — вот муж мой.",0,650,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О, ты моя, и твой я. Сколько раз",0,651,0,0],["v","Сменилось солнце прежде, чем обманы",0,652,0,0],["v","Богини осветило наконец!",0,652,0,0],["v","Слезы я лью, только сладкие слезы:",0,653,1,0],["v","От мук пережитых осталось",0,654,1,0],["v","В них больше отрады, чем горя.",0,655,1,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Что я скажу? Надеяться кто смел бы:",0,655,0,0],["v","Нежданного я прижимаю к сердцу…",0,656,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ты здесь, со мной. А кажется, давно ль",0,657,0,0],["v","Я верил в твой побег под кручи Иды,",0,657,0,0],["v","В несчастную твердыню Илиона?",0,658,0,0],["v","Богами заклинаю… Как могли",0,659,0,0],["v","Тебя из дома моего похитить?",0,660,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, горькое начало…",0,660,0,0],["v","О, горькие слова… Не трогай их…",0,661,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Нет, говори; что нам даруют боги,",0,662,0,0],["v","Того чуждаться слух не должен наш.",0,663,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Рассказывать мне страшно… Что за ужас!",0,664,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Все ж говори. О муках сладко слушать…",0,665,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","К Парису в руки, через пучину",0,665,0,0],["v","На веслах быстрых я не летела",0,666,0,0],["v","В объятья грешной его любви…",0,667,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но что за демон, что за рок могучий",0,668,0,0],["v","Тебя похитил из земли родной?",0,669,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Зевса и Майи сын, о мой любимый,",0,670,0,1],["v","В эту страну Гермес меня домчал…",0,671,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О, чудо! Кто ж послал его? Ужасно!",0,672,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ах, слезы, слезы увлажняют вежды.",0,673,0,0],["v","Меня сгубила Зевсова супруга.",0,674,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Как? Гера? Ей за что ж бы нас казнить?",0,675,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Вас, кляну я, ключи, тебя, светлая влага,",0,676,0,0],["v","Где красу освежали богини…",0,677,0,0],["v","И откуда судьи роковой приговор.",0,678,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но суд… и Гера… и твои несчастья…",0,679,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Чтоб у Париса отнять…",0,680,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не пойму!",1,680,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Дар, Кипридой обещанный…",0,680,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Бедная ты!",1,680,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да, бедная! В Египет повелела",0,681,0,0],["v","Она Гермесу унести меня.",0,682,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Так, значит, тот… владел твоей лишь тенью?",0,683,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","утвердительно кивая головой"],["v","А горе-то, горе-то в доме твоем!",0,684,0,0],["v","О мать, о кручина моя!",0,685,0,0],["sd","(Плачет.)"],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что хочешь сказать ты?",0,685,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["sd","Матери больше нет… Мой затянул позор Петлю на шее ей…"],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Увы!.. А дочь, — скажи мне, — Гермиона?",0,686,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Чуждая брака,",0,687,3,0],["v","Детей не ласкает",0,688,3,0],["v","И плачет всечасно",0,689,3,0],["v","О матери свадьбе.",0,690,3,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["sd","О, дом мой сгубивший Предатель Парис! Себе же готовил Ты лютую гибель И меднодоспешных Данайцев полкам!"],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А меня заставил демон",0,691,0,0],["v","Под обузою проклятья",0,692,0,0],["v","Бросить дом и край родной,",0,693,0,0],["v","На чужбину удалиться —",0,694,0,0],["v","Чтоб позор греховной свадьбы",0,695,0,0],["v","Неповинную терзал!",0,696,0,0],["sd","Пауза. <span class=\"ch\" data-ch=\"menelay\">Менелай</span> и <span class=\"ch\" data-ch=\"elena\">Елена</span> стоят молча, любуясь друг другом. Музыка умолкает."],["sp","Корифей"],["v","Коль вам теперь счастливая судьба",0,697,0,0],["v","Откроется — былое потускнеет.",0,698,0,0],["sp","Слуга"],["dir","стоявший до тех пор в почтительном отдалении, приближается"],["v","И я бы, царь, хотел с тобой делить",0,700,0,1],["v","Веселые минуты. Вижу радость,",0,700,0,0],["v","Да не могу никак ее понять.",0,701,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Ну что ж, старик, вступай в беседу с нами.",0,702,0,0],["sp","Слуга"],["v","Источник мук под Троей — не она?",0,703,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Нет. Боги нас обманывали, в руки",0,704,0,0],["v","Мои достался призрак роковой.",0,705,0,0],["sp","Слуга"],["v","Что ты сказал?",0,706,0,0],["v","Все муки — даром? И награда — призрак?",0,707,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Виною — Гера и богинь вражда.",0,708,0,0],["sp","Слуга"],["v","А это — подлинно твоя супруга?",0,709,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Тебе порукой слово в том мое.",0,710,0,1],["sp","Слуга"],["dir","радостно подходит к <span class=\"ch\" data-ch=\"elena\">Елене</span> и целует ей руку"],["v","О дочь моя! Богов чудесна воля,",0,710,2,0],["v","И неисповедимы их пути!",0,711,2,0],["v","Вращает мудро сила их людские",0,712,2,0],["v","Дела. И вот один проводит жизнь",0,712,2,0],["v","В трудах; другой, трудов не знавший, разом",0,713,2,0],["v","Находит гибель, никакой поруки",0,714,2,0],["v","Не получив от счастья своего.",0,715,2,0],["v","Ты и твой муж вкусили муки оба.",0,715,2,0],["v","Ты клеветой осилена, а царь",0,716,2,0],["v","Там за морем, в борьбе копейной жаркой,",0,717,2,0],["v","И что ж? Стараясь, ничего себе",0,717,2,0],["v","Не выстарал; а ныне, божьей воле",0,718,2,0],["v","Себя доверив, счастие нашел.",0,719,2,0],["sd","(С умилением подолгу всматриваясь в ее черты.)"],["v","Ни старому отцу, ни братьям ты",0,720,2,1],["v","Не нанесла позора, и своей ты",0,720,2,0],["v","Молвы не заслужила… Мне, царица,",0,721,2,0],["v","Так радостно припомнить, как <span class=\"ch\" data-ch=\"elena\">Елену</span>",0,722,2,0],["v","Мы с песнею венчальной из дворца",0,722,2,0],["v","Тиндара провожали: будто вижу",0,723,2,0],["v","Я факел тот, что нес у колесницы,",0,724,2,0],["v","<span class=\"ch\" data-ch=\"elena\">Елену</span> уносившей из ее",0,725,2,0],["v","Счастливого гнезда…",0,725,2,0],["v","Да, плох тот раб,",1,725,0,0],["v","Которому дела его хозяев",0,726,2,0],["v","Не дороги, который мук семьи",0,727,2,0],["v","И радостей не делит. Если в рабском",0,727,2,0],["v","Рожден я состоянье, пусть меня",0,728,2,0],["v","Рабом хотя считают благородным…",0,729,2,0],["v","Нет имени — я душу сберегу…",0,730,2,1],["v","Все ж лучше быть по имени рабом лишь,",0,731,2,0],["v","Чем на плечи одни, да оба зла:",0,732,2,0],["v","И рабский дух имей, и рабский жребий.",0,733,2,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Старик! Со мной в сраженьях ты делил",0,734,0,0],["v","И муки и труды; дели ж и радость.",0,735,0,0],["v","Ступай, скажи оставшимся друзьям",0,736,0,0],["v","Все, что нашел ты здесь и как дела",0,737,0,0],["v","Царевы обстоят. Пусть ждут, как раньше,",0,738,0,0],["v","На берегу борьбы моей исхода —",0,739,0,0],["v","Ее же чует уж душа моя.",0,740,0,1],["v","И если мне удастся из чужбины",0,740,0,0],["v","Жену похитить — быть им начеку,",0,741,0,0],["v","Чтоб, вместе нам соединившись, бегством",0,742,0,0],["v","От варваров, коль бог нам даст, уйти.",0,743,0,0],["sp","Слуга"],["v","Все сделаю, владыка…",0,744,0,0],["v","Каковы ж",1,744,0,0],["v","Оракулы! Ну разве же не плохи,",0,745,0,0],["v","Не лгут поди? Нет, видно, не легко",0,746,0,0],["v","Судьбу читать по языкам алтарным",0,747,0,0],["v","Иль птичьему… Какая слепота —",0,748,0,0],["v","Рассчитывать на птицу! Что ж бы было",0,749,0,0],["v","Калханту нам про облако сказать?",0,750,0,1],["v","Нет — дал своим он гибнуть… И зачем же",0,750,0,0],["v","Безмолвствовал Гелен? Его ведь город",0,751,0,0],["v","Мы разоряли — и за что? Ответ",0,752,0,0],["v","Я знаю: бог молчать велел пророкам.",0,752,0,0],["v","Но если так — к чему гаданья наши?",0,753,0,0],["v","Богам усердно жертвы приносить",0,754,0,0],["v","Должны мы и молиться, чтобы благо",0,754,0,0],["v","Нам посылали, а гаданья бросить.",0,755,0,0],["v","Они — для жизни лишь соблазн пустой;",0,756,0,0],["v","Коль ты лентяй — ты в огненных скрижалях",0,756,0,0],["v","Богатства не найдешь; пророк наш лучший —<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,757,0,0],["v","Решимость трезвая и здравый смысл.",0,758,0,0],["sd","(Уходит.)"],["sp","Корифей"],["v","Со старцем я согласна: ведовство",0,758,0,0],["v","Нам не к добру. Пусть бог тебя полюбит",0,759,0,0],["v","Вот лучшее гаданье для тебя.",0,760,0,1],["scene","Явление девятое","s12",3,12],["sd","Те же, без слуги."],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Все хорошо покуда. Как ты спасся,",0,760,0,0],["v","Скитаясь после илионских сеч, —",0,761,0,0],["v","Хоть пользы нет в рассказе, сердцу милой",0,762,0,0],["v","Желанна весть о милого трудах.",0,763,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","В одном ты слове и в одном желанье",0,764,0,0],["v","Сколь многие вопросы ставишь мне!",0,765,0,0],["v","К чему мне речь вести о грозной буре",0,765,0,0],["v","Эгейской, об огнях коварных старца",0,766,0,0],["v","Евбейского, о критских городах,",0,767,0,0],["v","О гаванях ливийских, о Персея",0,768,0,0],["v","Нагорных вышках? Сколько пережил я —<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,769,0,0],["v","И слух устанет твой, и сказом грустным",0,770,0,1],["v","Двойную скорбь я б причинил себе.",0,771,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ответ умней вопроса. Это так.",0,772,0,0],["v","Одно скажи: хребет пучины влажной",0,773,0,0],["v","Ты долго ли, скиталец, бременил?",0,774,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Сверх десяти, под Троей проведенных,",0,775,0,0],["v","Еще семь лет сменилось надо мной.",0,776,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","мрачно"],["v","Увы! Увы! Несчастный! Столько лет",0,777,0,0],["v","За жизнь дрожать… и угодить… на бойню…",0,778,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что говоришь? Убила ты меня!",0,779,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Из этих мест беги поспешным шагом:",0,780,0,1],["v","Убьет тебя жестокий господин.",0,781,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Постой! За что ж?.. Что я владельцу сделал?",0,782,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Помехою явился жениху.",0,783,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Как? У моей жены жених сыскался?",0,784,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да, дерзкий, он на это посягнул.",0,785,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Он из вельмож, иль это царь Египта?",0,786,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Он здесь царит. Протей — его отец.",0,787,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Так вот она — разгадка слов служанки!",0,788,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Какой? Ты в чьи ж стучался ворота?",0,789,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да в эти вот. И был, как нищий, прогнан.",0,790,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, горе мне! Как нищий! Горе мне!",0,791,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Я нищим был, хоть так не назывался.",0,792,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ты, значит, слышал все о сватовстве?",0,793,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Избегла ль ты его любви — не знаю.",0,794,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Твое я ложе чистым соблюла.",0,795,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Отрадно б было; но могу ли верить?",0,796,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ты видишь жалкий одр в тени гробницы?",0,797,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Постель из листьев, но при чем здесь ты?",0,798,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Здесь я молюсь, чтоб брака избежать.",0,799,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Нет алтаря? Иль здесь такой обычай?",0,800,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Блюдет меня гробница, словно храм.",0,801,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И увезти тебя домой нельзя мне?",0,802,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Меч, а не брак Атрида ожидает.",0,803,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Тогда из смертных всех несчастней я!",0,804,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Оставь же стыд! Беги, беги отсюда!",0,805,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А ты? Я Трою за тебя сразил!",0,806,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Все ж лучше так, чем гибнуть за меня!",0,807,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Совет труслив и Трои недостоин!",0,808,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Царя убить ты хочешь? Не надейся!",0,809,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Иль для железа он неуязвим?",0,810,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Как знать! Отвага ж свыше сил — безумна.",0,811,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что ж, молча мне отдаться палачу?",0,812,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Я выхода не вижу… Хитрость разве?",0,813,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И смерть отрадней в деле, чем без дела.",0,814,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Одна еще у нас надежда есть…",0,815,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","В чем? В золоте? В дерзанье? Иль моленье?",0,816,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Пусть о тебе царю не говорят!",0,817,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Кто ж скажет? Сам же он меня не знает.",0,818,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","таинственно"],["v","В союзе с ним там некто с силой бога…",0,819,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Меж этих стен таится вещий глас?",0,820,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Сестра царя живет тут, <span class=\"ch\" data-ch=\"feonoya\">Феоноя</span>.",0,820,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Пророческое имя. Что ж она?",0,821,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Все знает — обо всем царю расскажет.",0,822,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не скрыться мне тогда. Погибли мы.",0,823,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но если бы мы умолили деву…",0,824,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О чем?.. Куда свою ты клонишь речь?",0,825,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Чтоб о тебе не говорила брату.",0,826,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И мы тогда покинем этот край?",0,827,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ее раченьем — да; украдкой — нет.",0,828,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Улаживать, Елена, так тебе:",0,829,0,0],["v","Вы, женщины, скорее сговоритесь…",0,830,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О да! Ее колени я руками",0,830,0,0],["v","Обнять не раз готова, умоляя.",0,831,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","А если нас пророчица отвергнет?",0,832,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Тогда тебе убитым быть, <span class=\"ch\" data-ch=\"elena\">Елене</span> ж",0,832,0,0],["v","Постель царя-насильника делить!",0,833,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Изменница!.. Один предлог — насилье…",0,834,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Я головой твоей клянусь, что я…",0,835,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","перебивая ее"],["v","Что ты умрешь, не изменяя мужу?",0,835,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да, что умру, от одного с тобою",0,836,0,0],["v","Меча притом, и лягу близ тебя.",0,837,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","В знак верности коснись руки моей!",0,837,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","касаясь его руки"],["v","Да, если ты умрешь, глядеть на солнце",0,838,0,0],["v","Не буду я — в том вот тебе порука!",0,839,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","И я умру, коль царь тебя отнимет!",0,840,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но как нам смерть со славою стяжать?",0,840,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","На насыпи могильной за тобою",0,841,0,0],["v","С самим собой покончу я. Но раньше",0,842,0,0],["v","Мы испытаем силы, за жену.",0,843,0,0],["v","Кто хочет, выходи! Но лавра Трои",0,843,0,0],["v","Не посрамит ахейский вождь, его",0,844,0,0],["v","Не назовет Эллада малодушным.",0,845,0,0],["v","Как? Он, за славу коего Фетида",0,846,0,0],["v","Единственного сына отдала,",0,846,0,0],["v","Он, видевший окровавленный меч",0,847,0,0],["v","Аякса, он, перед которым Нестор",0,848,0,0],["v","Оплакивал дитя свое, отдаст<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,849,0,0],["v","Жену без боя? Нет… Коль боги мудры,",0,850,0,1],["v","Над воином, приявшим от врага",0,851,0,0],["v","Смерть честную, земля ложится пухом,",0,852,0,0],["v","А трус лежит на твердом ложе наг…",0,853,0,0],["sp","Корифей"],["v","Бессмертные! Покончит ли с несчастьем",0,854,0,0],["v","Танталов род у вас когда-нибудь?",0,855,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","смотревшая по направлению к дворцу"],["v","Увы! Увы! Судьба моя такая;",0,856,0,0],["v","Погибли мы: она сюда идет,",0,857,0,0],["v","Та вещая. Засовы заскрипели…",0,858,0,0],["v","Беги!.. Иль нет! Зачем? Не убежишь…",0,860,0,1],["v","Все, все известно ей. О, ужас! Гибну…",0,860,0,0],["v","Увы! Тебя затем ли меч щадил",0,861,0,0],["v","На берегах Скамандра, чтобы варвар",0,862,0,0],["v","В глаза тебе железом засверкал?",0,863,0,0],["scene","Явление десятое","s13",3,13],["sd","Из средних дверей появляется <span class=\"ch\" data-ch=\"feonoya\">Феоноя</span> в белой длинной одежде и сетке поверх распущенных волос. За нею толпа рабынь. Две рабыни идут перед нею: одна с высоко поднятым факелом и с чашей, в которой горит и дымится сера; другая, напротив, с опущенным."],["sp","<span class=\"ch\" data-ch=\"feonoya\">Феоноя</span>"],["dir","рабыням"],["v","Вы шествуйте передо мной: ты с светом",0,864,0,0],["v","Лучины и с пылающею серой,",0,865,0,0],["v","Истоком девственных эфирных недр,",0,865,0,0],["v","Чтоб чистое небесное дыханье",0,866,0,0],["v","Вливалось в грудь мне. Ты ж стезю мою,",0,867,0,0],["v","Коль кто-нибудь стопою нечестивой",0,868,0,0],["v","Ее сквернил, — ты пламени, раба,",0,869,0,0],["v","Ее отдай и, отрясая светоч,",0,870,0,1],["v","Очисти путь пророчицы. Воздав,",0,870,0,0],["v","Что я велю, богам, — обратно факел",0,871,0,0],["v","Пусть каждая возложит на очаг.",0,872,0,0],["sd","(Останавливается, долго смотрит в небо; мало-помалу на нее находит пророческий экстаз; она простирает руки к <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>, затем обращается к <span class=\"ch\" data-ch=\"elena\">Елене</span>.)"],["v","Что скажешь ты, Елена, о гаданье",0,873,0,0],["v","Моем теперь? Вот муж твой; кораблей",0,873,0,0],["v","И твоего подобья он лишился.",0,874,0,0],["sd","(К <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>.)"],["v","Да, горький, сколько ты уже прошел",0,875,0,0],["v","Тяжелых испытаний, а не знаешь,",0,876,0,0],["v","Что ждет тебя…",0,876,0,0],["sd","Пауза."],["v","Отсюда ль путь, иль здесь",1,876,0,0],["v","Его предел? Там из-за вас сегодня",0,877,1,0],["v","Мятется сонм Олимпа близ отца",0,878,1,0],["v","Державного. Но Гера на тебя",0,879,1,0],["v","Уже не копит злобы, как бывало;",0,880,1,1],["v","Вернуть тебя хотела бы она",0,880,1,0],["v","И с нею, гость:",0,881,1,0],["sd","(указывает на <span class=\"ch\" data-ch=\"elena\">Елену</span>)"],["v","пусть эллины увидят,",0,882,4,0],["v","Что призрачен был Александров брак,",0,883,1,0],["v","Киприды дар. Киприде же угодно",0,883,1,0],["v","Не допустить возврата твоего,",0,884,1,0],["v","Чтобы ее молва не обличила",0,885,1,0],["v","За тот обман, которым красоты",0,886,1,0],["v","Она стяжала первенство на Иде…<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,886,1,0],["sd","(Опускает глаза; пророческий экстаз проходит.)"],["v","Теперь зависит от меня: отдать",0,887,1,0],["v","Тебя царю в угоду Афродите.",0,888,1,0],["v","Иль, с Герою в согласье, — умолчав,",0,889,1,0],["v","Спасти тебя от брата.",0,890,1,1],["sd","(В борьбе с назревающим решением.)"],["v","От него ж",0,890,4,0],["v","Приказ — стеречь прибытие твое",0,891,1,0],["v","И доложить ему.",0,891,1,0],["sd","(Решившись.)"],["v","Так кто же в поле",0,892,4,0],["v","Пойдет царю сказать о Менелае?",0,893,1,0],["v","Так будет безопасней для меня.",0,893,1,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","бросаясь к коленям <span class=\"ch\" data-ch=\"feonoya\">Феонои</span>"],["v","О дева… Я с мольбой к твоим коленям",0,894,0,0],["v","Припала, и печальный этот прах",0,895,0,0],["v","Я телом покрываю… Я за нас",0,895,0,0],["v","Тебя молю обоих: за себя",0,896,0,0],["v","И этого несчастного. Как долго",0,896,0,0],["v","Его ждала я — и сейчас ножу",0,897,0,0],["v","Его отдам? О нет! О Менелае,",0,898,0,0],["v","Вернувшемся в объятия мои,",0,898,0,0],["v","Ты не расскажешь брату: заклинаю",0,899,0,0],["v","Тебя — спаси его; не отдавай",0,900,0,1],["v","Ты святости души своей в обмен",0,900,0,0],["v","За злую и неправедную милость!",0,901,0,0],["v","Насилье неугодно божеству:",0,902,0,0],["v","Приобретать — не похищать велело",0,903,0,0],["v","Оно нам достояние свое",0,903,0,0],["v","И отвергать богатство, если кривдой",0,904,0,0],["v","Оно добыто. Общим небеса",0,905,0,0],["v","Покровом нам, земля сырая общей",0,906,0,0],["v","Обителью; но дом и то, что в доме, —",0,906,0,0],["v","У каждого свои, и не велит",0,907,0,0],["v","Закон чужое отнимать насильем!<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,908,0,0],["v","На счастье нам — хоть моего страданья",0,909,0,0],["v","Ценой — отцу доверил твоему",0,910,0,1],["v","Меня Гермес, для мужа моего",0,910,0,0],["v","Чтобы сберег. Вот муж мой, взять с собою",0,911,0,0],["v","Меня он хочет. Но возьмет ли мертвой?",0,912,0,0],["v","И передаст ли мертвому живую",0,913,0,0],["v","Родитель твой? Да, вникни в волю бога,",0,913,0,0],["v","В отца завет! Вернуть иль не вернуть",0,914,0,0],["v","Они б велели ближним их добро?",0,915,0,0],["v","Вернуть, конечно. Неужели ж выше",0,916,0,0],["v","Поставишь ты греховный помысл брата,",0,916,0,0],["v","Чем благородство твоего отца?",0,917,0,0],["v","А если ты, пророчица, которой",0,918,0,0],["v","Свою и боги открывают волю,",0,919,0,0],["v","Отца святую правду оскорбишь,",0,920,0,1],["v","Неправую спасая правду брата, —",0,920,0,0],["v","Что за позор! Все тайны божества",0,921,0,0],["v","Постичь, о сущем и не сущем верно",0,922,0,0],["v","Судить, — а божью правду попирать!",0,922,0,0],["v","Ну, а затем… Ты видишь: море бед",0,923,0,0],["v","Мою ладью колышет, — о, спаси,",0,924,0,0],["v","Спаси меня, союзницей да будет",0,924,0,0],["v","И жалость справедливости твоей!",0,925,0,0],["v","Ведь человека нет, кого б мое",0,926,0,0],["v","Не возмущало имя. Вся Эллада",0,926,0,0],["v","Молвы полна о той, что, изменив",0,927,0,0],["v","Супругу, на злаченые чертоги",0,928,0,0],["v","Польстилась. О, отдай отчизну нам!",0,928,0,0],["v","Коли вернусь я в Спарту, — очевидной",0,929,0,0],["v","Всем эллинам ты сделаешь игру",0,930,0,1],["v","Богов и верность строгую <span class=\"ch\" data-ch=\"elena\">Елены</span>;",0,930,0,0],["v","Себе верну жены я честной имя",0,931,0,0],["v","И выдам дочь. Кто ж иначе моей",0,932,0,0],["v","Захочет Гермионы? Я скитанья",0,933,0,0],["v","Покончила бы горькие тогда",0,933,0,0],["v","И достоянием родного дома",0,934,0,0],["v","Свободно б насладилась. Если б муж",0,935,0,0],["v","Убит был на чужбине — в слез потоках",0,936,0,0],["v","Я б утешение вдовству нашла;",0,936,0,0],["v","Но ведь он здесь, спасен от бед, от смерти,",0,937,0,0],["v","И у меня отнять его хотят…",0,938,0,0],["v","Царевна! Милосердье! Правды отчей",0,939,1,0],["v","Ты оживи нам память. Выше славы",0,940,0,1],["v","Для человека нет, как на отца",0,941,0,0],["v","Великою душою быть похожим.",0,942,0,0],["sp","Корифей"],["v","Я тронута твоей мольбою, мне",0,943,0,0],["v","Так жаль тебя! Но речи <span class=\"ch\" data-ch=\"menelay\">Менелая</span>",0,944,0,0],["v","Я жду: что скажет он за жизнь свою?",0,945,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","К твоим ногам я не решусь припасть,",0,946,0,0],["v","Слезами обливаясь: лавры Трои",0,947,0,0],["v","Позорить малодушьем непристойно.",0,948,0,0],["v","Хоть говорят, что благородных красит",0,950,0,1],["v","В беде с ресниц упавшая слеза,",0,950,0,0],["v","Я не поставлю этой красоты —",0,951,0,0],["v","Коль красота тут есть — превыше духа",0,952,0,0],["v","Отважного.",0,953,0,0],["v","Коли подскажет сердце",1,953,0,0],["v","Тебе, жена, пришельца уберечь,",0,954,0,0],["v","Когда жены он требует по праву, —",0,955,0,0],["v","Отдай жену ему и сбереги;",0,955,0,0],["v","А скажешь «нет» — ну, что же? Не впервые",0,956,0,0],["v","Мне принимать удар судьбы: дурной",0,957,0,0],["v","Зато себя ты выставишь навеки.",0,958,0,0],["v","А что меня достойно, справедливо",0,959,1,0],["v","И за душу больней тебя возьмет,",0,960,0,1],["v","То я скажу, припав к отца могиле:",0,960,0,0],["v","\"О старец, каменной гробницы житель!",0,961,0,0],["v","Я требую супруги от тебя!",0,961,0,0],["v","Верни ее: сам Зевс ее доверил",0,962,0,0],["v","Тебе, чтоб мужу ты ее сберег.",0,962,0,0],["v","Не можешь, знаю, мертвою рукою",0,963,0,0],["v","Ее живому передать: внуши ж",0,964,0,0],["v","Ты дочери, чтоб имени отца",0,964,0,0],["v","Священного на жертву злым укорам",0,965,0,0],["v","Не отдавала вещая, когда",0,965,0,0],["v","К тебе в чертог глубокий доноситься",0,966,0,0],["v","Моления людские будут. Все",0,967,0,0],["v","В ее руках теперь. И ты, подземный",0,967,0,0],["v","Аид, мне будь союзником! Иль мало",0,968,0,0],["v","Из-за нее ты принял тел людских",0,968,0,0],["v","Там, под булата моего грозою?",0,969,0,0],["v","Ты получил вперед награду: дай же",0,970,0,1],["v","Иль им вторичной жизнью зацвести,",0,971,0,0],["v","Иль ей со славой отчею сравняться",0,972,0,0],["v","И возвратить супругу мне мою\".",0,973,0,0],["sd","(Опять обращаясь к <span class=\"ch\" data-ch=\"feonoya\">Феоное</span>.)"],["v","А если вы отнимете ее,",0,974,0,0],["v","К ее словам прибавить я имею",0,975,0,0],["v","Еще одно. Мы клятвою связали",0,976,0,0],["v","Себя, — и вот что будет, дева. Если",0,977,0,0],["v","Придет твой брат, я с ним вступаю в бой:",0,978,0,0],["v","Иль он падет, иль я — рассказ несложен.",0,979,0,0],["v","А если вызова не примет он",0,980,0,1],["v","И голодом просителей у гроба",0,980,0,0],["v","Неволить вздумает, — ее убить",0,981,0,0],["v","Поклялся я и тот же меч двуострый",0,982,0,0],["v","И в собственную грудь вонзить — вот здесь,",0,983,0,0],["v","На насыпи могильной, чтобы крови",0,984,0,0],["v","Струи в подземный терем потекли.",0,985,0,0],["v","И двое нас на тесаном гробу",0,985,0,0],["v","Уляжется тебе укором вечным",0,986,0,0],["v","И на позор отцу. Но на моей",0,987,0,0],["v","Жене ни брат твой, ни другой, царевна,",0,988,0,0],["v","Не женится. Коль не домой и в Спарту,",0,989,0,0],["v","Ее возьму в обитель мертвых я.",0,990,0,1],["v","Вот речь моя. А слез и женских жалоб",0,990,1,0],["v","Не жди: не жалким — сильным быть хочу.",0,991,0,0],["v","Коль хочешь — убивай: позорной смерти",0,992,0,0],["v","Я не приму. Но лучше — снизойди",0,993,0,0],["v","К моим словам: тогда и я <span class=\"ch\" data-ch=\"elena\">Елену</span>",0,994,0,0],["v","Верну себе, и ты — венец святой.",0,995,0,0],["sp","Корифей"],["v","Тебе вершить, юница, эти речи:<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,995,0,0],["v","Всех примири благим своим судом.",0,996,0,0],["sp","<span class=\"ch\" data-ch=\"feonoya\">Феоноя</span>"],["v","Во мне и кровь и ум благочестивы.",0,997,0,0],["v","Я и себя блюду, и честь отца",0,998,0,0],["v","Не запятнаю; брату же услугу",0,999,0,0],["v","Себе в позор не вправе оказать.",0,1000,0,1],["v","Великая святыня Правды в сердце",0,1001,0,0],["v","Воздвигнута моем; она — Нерея",0,1002,0,0],["v","Дар, Менелая, — я сохраню ее.",0,1003,0,0],["v","И раз улыбка Геры над тобою —<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,1004,0,0],["v","Я с нею заодно. Киприда же…",0,1005,0,0],["v","Гневить ее не буду, но не с нею",0,1006,0,0],["v","Мои пути: я — дева навсегда.",0,1007,0,0],["v","В чем ты отца корил за прагом смерти,",0,1008,1,0],["v","В том я с тобой согласна: я б виновна",0,1010,0,1],["v","Была, не возвратив тебе жены;",0,1011,0,0],["v","Ведь он бы вас соединил, будь жив он.",0,1012,0,0],["v","А за дела такие есть возмездье",0,1013,0,0],["v","И под землей, и здесь для всех людей.",0,1014,0,0],["v","Хоть не живет умерший, дух его",0,1015,0,0],["v","Сам вечен, в вечный принятый эфир.",0,1016,0,0],["v","И вот ответ мой краткий: вашей тайны",0,1017,1,0],["v","Не выдам я и брата дерзновенью",0,1018,0,0],["v","Мирволить не намерена; ему",0,1019,0,0],["v","Не на позор я окажу услугу,",0,1020,0,1],["v","Направив грешника на путь добра.",0,1020,0,0],["v","Исход придумайте вы сами; я же,",0,1021,1,0],["v","Покинув вас, в молчанье погружусь.",0,1022,0,0],["v","С мольбы богам начните. Ты, Елена,",0,1023,0,0],["v","Киприду упроси тебя вернуть",0,1024,0,0],["v","На родину; а Геру — чтобы ласки",0,1025,0,0],["v","Своей не изменяла. Ты ж, отец",0,1025,0,0],["v","Почивший наш, — покуда в этом сердце",0,1026,0,0],["v","Не смолкнет кровь, не будешь средь людей",0,1027,0,0],["v","Прославлен нечестивцем, и хвала",0,1028,0,0],["v","Вкруг имени великого не смолкнет.",0,1029,0,0],["sd","(Уходит в двери со свитой.)"],["sp","Корифей"],["v","Нет для неправды прочного успеха,",0,1030,0,1],["v","Но правде и надежда верный друг!",0,1031,0,0],["scene","Явление одиннадцатое","s14",3,14],["sd","<span class=\"ch\" data-ch=\"elena\">Елена</span> и <span class=\"ch\" data-ch=\"menelay\">Менелай</span> в том же положении, как и до прихода <span class=\"ch\" data-ch=\"feonoya\">Феонои</span>."],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","От девы нам препятствия не будет;",0,1032,0,0],["v","Речь за тобой отныне, <span class=\"ch\" data-ch=\"menelay\">Менелай</span>.",0,1033,0,0],["v","Придумай способ общего спасенья.",0,1034,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","после некоторого раздумья"],["v","Послушай же… Своя ты в этом доме,",0,1035,0,0],["v","И, верно ж, ты имеешь там друзей.",0,1036,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","оживленно"],["v","К чему ведешь ты речь? Знать, есть надежда",0,1037,0,0],["v","Счастливого исхода нам с тобой?",0,1038,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Кто тут у вас приставлен к колесницам?",0,1039,0,0],["v","Ты лошадей могла бы раздобыть?",0,1040,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Конечно да. Но незнакомой степью,",0,1041,0,0],["v","Средь варваров, далеко ль убежим?",0,1042,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, ты права… А если бы с тираном",0,1043,0,0],["v","Украдкою покончить? Вот и меч.",0,1044,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Нет, вещая б тебя не допустила",0,1045,0,0],["v","Убить царя, — он брат ей, не забудь.",0,1046,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но корабля здесь нет же для побега,",0,1047,0,0],["v","А мой — увы! — похоронен в волнах.",0,1048,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Послушай женской мудрости. Согласен",0,1049,0,0],["v","При жизни ты за мертвого прослыть?",0,1050,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","нерешительно"],["v","Примета все ж. Но коль к добру — готов я,",0,1051,0,0],["v","Хоть и живой, за мертвого прослыть.",0,1052,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Пред варваром тебя оплачу я,",0,1053,0,0],["v","Я волосы сниму, надену траур.",0,1054,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Не вижу здесь спасения для нас…",0,1055,0,0],["v","Какой-то стариной от средства веет.",0,1056,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Я умолю тирана, чтобы дал",0,1057,0,0],["v","Мне помянуть погибшего в пучине.",0,1058,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но что же даст тебе пустой обряд?",0,1059,0,0],["v","Без корабля куда ж уйдем, Елена?",0,1060,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Пускай ладью снарядит нам, — убор",0,1061,0,0],["v","Почившему свезти в объятья моря.",0,1062,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Все хорошо придумано. А вдруг",0,1063,0,0],["v","Предложит царь поминки, но на суше?",0,1064,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Обычая в Элладе, скажем, нет,",0,1065,0,0],["v","Чтоб поминать на суше утонувших.",0,1066,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, это так. Конечно, я с тобой",0,1067,0,0],["v","Плыву, убор везем мы вместе в море.",0,1068,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ты должен быть готов, да и твои",0,1069,0,0],["v","Товарищи, какие уцелели.",0,1070,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","О, только б нам на якоре ладью!",0,1071,0,0],["v","Все, как один, там будут, и с мечами.",0,1072,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Об этом ты заботься. Только б нам",0,1073,0,0],["v","В попутчики послали боги ветер!",0,1074,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Я ль муками того не заслужил?",0,1075,0,0],["v","Но вестника кто смерти разыграет?",0,1076,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ты сам. Скажи, что уцелел один",0,1077,0,0],["v","И что Атрид погиб перед тобою.",0,1078,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, мой наряд к рассказу подойдет:",0,1079,0,0],["v","Я потерпел крушенье — это видно.",0,1080,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Наряд нам в руку. Не с руки потеря",0,1080,0,0],["v","Была; на пользу вышла и беда.",0,1081,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Итак, войти ль с тобой мне во дворец?",0,1082,0,0],["v","Иль у гробницы пребывать спокойно?",0,1083,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Останься здесь. На случай, если б царь",0,1084,0,0],["v","На произвол решился, — гроб защитой,",0,1085,0,0],["v","А меч угрозой будет. Во дворце",0,1085,0,0],["v","Я локоны скосить отдам железу,",0,1086,0,0],["v","А светлых риз отраду заменю",0,1087,0,0],["v","Одеждою печальной, и ланиты",0,1088,0,0],["v","Следы ногтей кровавые хранить<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,1089,0,0],["v","Обречены. На острие ножа",0,1090,0,1],["v","Моя судьба. Обман угадан — смерть;",0,1090,0,0],["v","А удался — ты, родина, спасенье!",0,1091,0,0],["v","Владычица! Ты, ложа красота",0,1092,0,0],["v","Кронидова, пошли желанный отдых",0,1093,0,0],["v","На долю двух несчастных: к небесам",0,1094,0,0],["v","С мольбой подъяв десницы, мы взываем",0,1095,0,0],["v","К твоим чертогам звездным. Ты же, дочь",0,1095,0,0],["v","Дионы, ты, Киприда, — ты, Парисом",0,1096,0,0],["v","Венчанная ценой моей измены, —",0,1097,0,0],["v","О, не губи нас! Или мало муки,<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,1098,0,0],["v","Иль мало я позора приняла,",0,1099,0,0],["v","Отдав чужому — не себя, но имя?",0,1100,0,1],["v","Коль умереть должна я, пусть же дома",0,1100,0,0],["v","Умру, по крайней мере. О, зачем же",0,1101,0,0],["v","Ты в нашем горе ненасытна так?",0,1102,0,0],["v","Ах, все любовь, измены, и коварства",0,1102,0,0],["v","Ты создаешь, и негу роковую,",0,1103,0,0],["v","От коей дом в потоках крови тонет…",0,1104,0,0],["v","А если б в меру ты сердца ласкала,",0,1104,0,0],["v","Из всех богинь была бы ты желанней",0,1105,0,0],["v","Для человека; так я и сужу.",0,1106,0,0],["sd","(Уходит.)"],["scene","Первый музыкальный антракт","s15",3,15],["sp","Хор"],["str","Строфа I"],["v","Тебя, соловей, из свежей зеленой рощи,",0,1106,3,0],["v","Где песни в кустах",0,1107,4,0],["v","Росистых так нежны,",0,1108,4,0],["v","Тебя я зову, певец из певцов…",0,1108,3,0],["v","Бурые перья твое горло одели",0,1109,3,0],["v","С его сладкозвучным рыданьем…",0,1110,3,1],["v","Песне печальной моей помоги, соловей, своей трелью…",0,1111,0,0],["v","Песне о бедной <span class=\"ch\" data-ch=\"elena\">Елене</span>,",0,1112,4,0],["v","О роке троянок, гонимых",0,1113,4,0],["v","Грозным ахейцем,",0,1114,4,0],["v","Роке, нависшем с тех пор, как приехал ужасный жених",0,1115,0,0],["v","На своей заморской ладье,",0,1116,4,0],["v","И как он на гибель Приама",0,1117,4,0],["v","С ложа <span class=\"ch\" data-ch=\"elena\">Елену</span> сманил, спартанского ложа,",0,1120,3,1],["v","Волей Киприды.",0,1121,4,0],["str","Антистрофа I"],["v","О, скольких — увы! — ахейцев сразили копья",0,1122,3,0],["v","И каменный град!..",0,1123,4,0],["v","О, скольких ахейцев!..",0,1124,4,0],["v","Печальный Аид их тени объял;",0,1125,3,0],["v","В сирых остались домах жены; им косы",0,1126,3,0],["v","Отрезал булат златые",0,1127,3,0],["v","В сирых чертогах… Их много сгубил и пловец одинокий;",0,1128,0,0],["v","Там, на Евбее, огни он",0,1129,4,0],["v","Зажег, чтоб о скрытые скалы",0,1130,4,1],["v","Лодки разбило.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,1131,4,0],["v","Их обмануло светило вдали… И Малея берет",0,1132,0,0],["v","Жестокую дань, когда",0,1133,4,0],["v","Провозил роковую добычу",0,1134,4,0],["v","Царь <span class=\"ch\" data-ch=\"menelay\">Менелай</span>, — тот призрак, из облака слитый",0,1135,3,0],["v","Геры искусством…",0,1136,4,0],["str","Строфа II"],["v","Бог, или случай, иль демон,",0,1137,0,0],["v","Но как глубоко ни спускайся,",0,1138,0,0],["v","Силясь постичь смертных природу ты, —",0,1139,0,0],["v","Видишь ты только, что боги",0,1140,0,1],["v","Туда и сюда нами мечут.",0,1140,0,0],["v","Тут утонул ты, а вынырнул там,",0,1141,0,0],["v","И судьба над расчетом глумится.",0,1142,0,0],["v","Ты, о Зевса дитя, — в объятия Леды",0,1143,1,0],["v","Птицей затем ли, скажи нам, спускался Кронид,",0,1144,1,0],["v","Чтобы по эллинской шири потом",0,1145,1,0],["v","Зевсовой дочери имя носилось",0,1146,1,0],["v","С кличкой изменницы низкой,",0,1147,1,0],["v","Безбожной?.. Я даже не знаю,",0,1148,1,0],["v","Можно ли верить божественной сказке,",0,1149,1,0],["v","Что некогда людям правдой казалась.",0,1150,1,1],["str","Антистрофа II"],["v","Смертные, это безумье,",0,1150,1,0],["v","Что острой лишь медью копейной",0,1151,0,0],["v","Доблесть добыть сердцем горите вы…",0,1152,0,0],["v","Или предела страданьям",0,1153,0,0],["v","Не будет для смертного рода?",0,1154,0,0],["v","Если кровавым лишь боем решать",0,1155,0,0],["v","Споры будем, они не умолкнут",0,1156,0,0],["v","Меж людьми никогда. За что Приамиды,",0,1157,1,0],["v","Эту покинув юдоль, в поддонное царство сошли?",0,1158,1,0],["v","Разве нельзя было спор разрешить",0,1159,1,0],["v","Твой, о Елена, словами? Зачем же",0,1160,1,1],["v","Пламенным стрелам, скажи нам,",0,1160,1,0],["v","Было летать, как перунам, вонзаясь",0,1161,1,0],["v","В старые башни Пергама?",0,1162,1,0],["v","И жизнь тебе к горю горе приносит.",0,1163,1,0],["act","Действие третье","a4","III"],["scene","Явление двенадцатое","s16",4,16],["sd","У гробницы, прижавшись к ней в позе молящего, сидит <span class=\"ch\" data-ch=\"menelay\">Менелай</span>. <span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>, за ним свита, охотники, собаки. Он подходит к гробнице отца со стороны, противоположной той, где сидит <span class=\"ch\" data-ch=\"menelay\">Менелай</span>. Из ворот ему навстречу почтительно выходит стража."],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","с молитвенным жестом по направлению к гробнице"],["v","Привет тебе, отцовский гроб! Тебя",0,1164,0,0],["v","Я схоронил, Протей, у входа, чтобы",0,1165,0,0],["v","Приветствовать почаще. Всякий раз,",0,1166,0,0],["v","Как покидаю дом или готовлюсь",0,1167,0,0],["v","Войти в него, молюсь тебе, отец!",0,1168,0,0],["sd","(Свите.)"],["v","Приспешники, ведите по местам",0,1169,0,0],["v","Собак, а в доме царском нашем сети",0,1170,0,1],["v","Развесьте.",0,1170,0,0],["sd","Свита уходит; <span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span> с раздражением обращается к начальнику стражи."],["v","О, я слов не нахожу",1,1170,0,0],["v","Себе в укор! Не мы ль караем смертью",0,1171,2,0],["v","Бессовестных? И что же? Вот опять",0,1172,2,0],["v","Ахеец объявился: видно, стражу<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,1173,2,0],["v","Он обманул. Лазутчик; а не то —",0,1173,2,0],["v","На выручку <span class=\"ch\" data-ch=\"elena\">Елене</span>. Ну попался б, —",0,1174,2,0],["v","И не уйдет от смерти он.",0,1175,2,0],["sd","(Озираясь кругом и никого не видя у гробницы.)"],["v","Ба… Ба…",0,1176,4,0],["v","Да дело-то уж сладилось, пожалуй:",0,1176,2,0],["v","На ступенях и след простыл. И дочь",0,1177,2,0],["v","Тиндарова уж далеко отсюда…",0,1178,2,0],["sd","(Опять обращаясь к страже.)"],["v","Гей вы! Запоры прочь, из стойла вон",0,1179,2,0],["v","Коней, готовьте колесницы, слуги!",0,1180,4,1],["v","Или трудов нам жалко, чтоб не дать",0,1181,2,0],["v","Желанной птичке выпорхнуть?.. Постойте:",0,1182,2,0],["v","Да вот она… добыча… не ушла,",0,1183,2,0],["v","Вот из дворца выходит.",0,1184,2,0],["scene","Явление тринадцатое","s17",4,17],["sd","Те же и <span class=\"ch\" data-ch=\"elena\">Елена</span> (выходит из ворот в трауре и с подрезанными волосами)."],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Гей, Елена!",0,1185,0,0],["v","А где ж твой пеплос белый и зачем",0,1186,0,0],["v","Ты в черное оделась? Что ж чела",0,1187,0,0],["v","Не кроется уж образ благородный",0,1188,0,0],["v","Венцом косы и свежею росой",0,1189,0,0],["v","Орошены ланиты? Сновиденье",0,1190,0,1],["v","Тебя смутило ночью иль молва",0,1190,0,0],["v","С далекого Еврота прилетела?",0,1191,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","с притворным смирением"],["v","О господин… О да, мой господин!",0,1192,0,0],["v","<span class=\"ch\" data-ch=\"elena\">Елены</span> нет. Одно воспоминанье",0,1193,0,0],["v","Перед тобой встает, <span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>.",0,1193,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Тебя постигло горе? Но какое ж?",0,1194,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, Менелай… о, ужас… звука нет",0,1195,0,0],["v","У голоса… чтобы сказать… он умер…",0,1196,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Не радостна мне весть твоя, хоть счастье",0,1196,0,0],["v","Она мне предвещает; но откуда",0,1197,0,0],["v","Узнала ты об этом? От сестры?",0,1198,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да… только есть еще свидетель смерти.",0,1199,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А, он пришел? И с достоверной вестью?",0,1200,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да, он пришел. И пусть туда уходит,",0,1200,0,0],["v","Куда… уйти ему желаю я.",0,1201,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Кто ж он? И где? Хочу узнать яснее.",0,1202,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","указывая на <span class=\"ch\" data-ch=\"menelay\">Менелая</span>"],["v","Да вот он сам: дрожит, к могиле жмется.",0,1203,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","О, Аполлон! Как жалко он одет!",0,1204,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да… так же жалко, мнится, как и муж мой.",0,1205,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Но кто он? И откуда к нам явился?",0,1206,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Из греков он, ахеец, с мужем плавал.",0,1207,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А смертью взят какой же <span class=\"ch\" data-ch=\"menelay\">Менелай</span>?",0,1208,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Печальней нет… во влажной бездне моря…",0,1209,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А по каким носился он волнам?",0,1210,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Ливийские его разбили скалы.",0,1211,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А этот… спутник… как же уцелел?",0,1212,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Трус иногда счастливее отважных.",0,1213,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А где ж он спасся средь обломков судна?",0,1214,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Там, где бы лучше сам погиб — не муж мой!",0,1215,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","с выражением неудовольствия"],["v","Погиб — твой муж. А он на чем доплыл?",0,1216,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Нашли его и подняли пловцы.",0,1217,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А где злой дух, тебя сменивший в Трое?",0,1218,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Про призрак говоришь ты? Он растаял.",0,1219,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","О, Троя! О, Приам! Погибли даром!",0,1220,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, их несчастье и меня коснулось!",0,1221,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Что ж царь? Зарыт? Иль так и брошен он?",0,1222,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","ломая руки"],["v","Он брошен так… о, муки горше мук!",0,1223,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Вот отчего не стало длинных кос…",0,1224,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Здесь или там, в пучине, он мне дорог.",0,1225,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","недоверчиво"],["v","По мертвом ли то плачешь ты? Смотри!",0,1226,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Иль обмануть сестру твою возможно?",0,1227,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Конечно нет. Ну что ж? Гробницу бросишь?",0,1228,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, не глумись! Хоть мертвых пощади!",0,1229,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Ты мертвому верна, меня ж бежишь!..",0,1230,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","опустив голову, тихо"],["v","Да нет же, я на брак с тобой готова.",0,1231,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","радостно"],["v","Хоть поздно — что ж! Спасибо и на этом.",0,1232,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Но просьба есть. Мы прошлое забудем…",0,1233,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Проси; на милость милостью отвечу.",0,1234,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Я предлагаю договор тебе.",0,1235,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Всегда готов. Во мне вражды уж нет.",0,1236,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О, дай обнять колена… раз ты друг мне…",0,1237,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Да объясни ж… Ты молишь-то о чем?",0,1238,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Похоронить покойного хочу я.",0,1239,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Но где же он? Иль похоронишь тень?",0,1240,0,1],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Есть эллинский обряд: погибших в море…",0,1240,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Кончай! И мудры ж в этом Пелопиды!",0,1241,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Заочно в тканях ризы хоронить.",0,1242,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Что ж, хорони! В Египте место есть.",0,1243,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Не так хороним утонувших мы.",0,1244,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А как? Неведом эллинский обряд мне.",0,1245,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Мы отдаем волнам убор умерших.",0,1246,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Итак, что дать тебе велишь для трупа?",0,1247,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","указывая на <span class=\"ch\" data-ch=\"menelay\">Менелая</span>"],["v","Он лучше знает; я же непривычна, —",0,1248,0,0],["v","Там, в Спарте, горя не знавала я.",0,1249,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","к <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>"],["v","Мой гость, ты весть отрадную принес…",0,1250,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Но все ж не мне и не погибшей жертве.",0,1251,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","с досадой"],["v","Как утонувших хоронить велишь?<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,1252,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Смотря кого… и честь по состоянью…",0,1253,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","За средствами уж я не постою.",0,1254,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Сперва подземным кровь приносим мы.",0,1255,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Чью кровь? Скажи — отказа не услышишь.",0,1256,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","По выбору… что дашь, то и годится.",0,1257,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","У варваров берется конь иль бык.",0,1258,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Что хочешь дай, но только без порока.",0,1259,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Средь стад моих есть выбрать из чего…",0,1260,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Для мертвеца пустое ложе нужно.",0,1261,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","И будет… Что потребуешь еще?",0,1262,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Оружие из меди… царь был воин…",0,1263,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Мой дар достоин будет Пелопидов.",0,1264,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Плодов земли ты припасешь нам лучших.",0,1265,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Пусть так; но как же морю передашь?",0,1266,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Корабль нам нужен и гребцы на нем.",0,1267,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","насупив брови"],["v","На нем отъехать далеко придется?",0,1268,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Чтоб берег с виду потерял его.",0,1269,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","с растущей недоверчивостью"],["v","Такой с чего ж обычай завели вы?",0,1270,0,1],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","внушительно"],["v","Чтоб скверны нам не возвратил прибой.",0,1270,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","вздрагивая"],["v","Вам дам я быстрый финикийский струг.",0,1271,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","двусмысленно"],["v","Благодарю; утешишь <span class=\"ch\" data-ch=\"menelay\">Менелая</span>.",0,1271,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Но ты свершишь поминки без <span class=\"ch\" data-ch=\"elena\">Елены</span>?",0,1272,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","У нас лежит последний этот долг",0,1273,0,0],["v","На матерях, на женах и на детях…",0,1273,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Выходит так, что совершить обряд",0,1274,0,0],["v","Никто другой не может, как <span class=\"ch\" data-ch=\"elena\">Елена</span>?",0,1275,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["v","Да, отказать в почете мертвецу",0,1275,0,0],["v","Я б не дерзнул… Не позволяют боги.",0,1276,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","после минутного колебания"],["v","Пусть будет так… Ведь мне же лучше, если",0,1276,0,0],["v","Я благочестью научу жену.",0,1277,0,0],["v","Итак, возьми для трупа из чертога",0,1278,0,0],["v","Убор могильный. Да и сам ты, гость,",0,1278,0,0],["v","Коль угодишь <span class=\"ch\" data-ch=\"elena\">Елене</span>, не с пустыми",0,1279,0,0],["v","От нас уйдешь руками. Ты принес",0,1280,0,1],["v","Приятные нам вести; так лохмотья",0,1280,0,0],["v","Одеждою приличной замени",0,1281,0,0],["v","Да забери припасов на дорогу:",0,1282,0,0],["v","Ведь исстрадался ты порядком, вижу.",0,1283,0,0],["sd","(К <span class=\"ch\" data-ch=\"elena\">Елене</span>.)"],["v","А ты, жена… былого не вернуть:",0,1284,0,0],["v","Зачем себя терзаешь? <span class=\"ch\" data-ch=\"menelay\">Менелаю</span>",0,1285,0,0],["v","Покойному ты солнца не отдашь!",0,1285,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","с улыбкой"],["v","Итак, царица, за тобою дело.",0,1286,0,0],["v","Люби супруга истинного; тот же,",0,1287,0,0],["v","Что потерял свои права, пусть канет",0,1288,0,0],["v","В забвения пучину. Вот исход",0,1289,0,0],["v","Удачнейший. А я — пусть только бог мне",0,1290,0,1],["v","В Элладу даст возврат благополучный! —",0,1290,0,0],["v","Позорящие толки о тебе",0,1291,0,0],["v","Немедля прекращу, коль верно службу",0,1292,0,0],["v","Сослужишь ты супругу своему.",0,1293,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","И сослужу. Не будет недоволен",0,1294,0,0],["v","Женою муж: ты сам вблизи увидишь.",0,1295,0,0],["v","Однако, горький, в дом войди; купель",0,1295,0,0],["v","Пусть тело освежит, покроют ризы",0,1296,0,0],["v","Достойные. Хочу без промедленья",0,1297,0,0],["v","Тебя пригреть: ты с большею любовью",0,1298,0,0],["v","Свершишь над мужем горестный обряд,",0,1299,0,0],["v","Когда и сам достойное получишь.",0,1300,0,1],["sd","Все уходят в дом."],["scene","Второй музыкальный антракт","s18",4,18],["sp","Хор"],["str","Строфа I"],["v","Мать блаженных, гор царица,",0,1300,0,0],["v","Быстрым летом уносима,",0,1301,0,0],["v","Ни ущелий густолесых",0,1302,0,0],["v","Не забыла, ни потоков,",0,1303,0,0],["v","Ни морей о грозном шуме:",0,1304,0,0],["v","Деву-дочь она искала,",0,1305,0,0],["v","Что назвать уста не смеют,",0,1305,0,0],["v","И звучали при движенье",0,1306,0,0],["v","Погремушки Диониса",0,1307,0,0],["v","И пронзительно и ярко!",0,1308,0,0],["v","А у гордой колесницы",0,1309,0,0],["v","Близ ее запряжки львиной",0,1310,0,1],["v","За царевною в погоню,",0,1310,0,0],["v","Что из светлых хороводов",0,1311,0,0],["v","От подруг похитил дерзкий,",0,1312,0,0],["v","Две богини мчались рядом:",0,1312,0,0],["v","Лук горел на Артемиде;",0,1313,0,0],["v","У Паллады меднобронной —",0,1314,0,0],["v","Острие копья и очи;",0,1315,0,0],["v","Но отец богов, взирая",0,1315,0,0],["v","С высоты небес, иные",0,1316,0,0],["v","Создавал в уме решенья.",0,1317,0,0],["str","Антистрофа I"],["v","И скитаньем быстролетным,",0,1317,0,0],["v","Не напав на след коварный",0,1318,0,0],["v","Похитителя ребенка,",0,1319,0,0],["v","Утомленная богиня",0,1320,0,1],["v","Наконец остановилась.",0,1320,0,0],["v","Под Деметрою белела",0,1321,0,0],["v","Иды высь снеговенчанной…",0,1322,0,0],["v","Там, среди обледенелых",0,1323,0,0],["v","Скал, дает богиня волю",0,1324,0,0],["v","Жгучим приступам печали:",0,1325,0,0],["v","С той поры бесплодных пашен",0,1326,0,0],["v","Труд зелеными не делал.",0,1327,0,0],["v","Поколенья погибали.",0,1328,0,0],["v","Не дала богиня даже",0,1329,0,0],["v","Для утехи стад вздыматься",0,1330,0,1],["v","В луговинах травам сочным…",0,1330,0,0],["v","В городах явился голод,",0,1331,0,0],["v","И богам не стало жертвы,",0,1332,0,0],["v","Не пылал огонь алтарный,",0,1333,0,0],["v","Воды светлые умолкли.",0,1334,0,0],["v","Так упорно, безутешно",0,1335,0,0],["v","Мать-Деметра тосковала.",0,1336,0,0],["str","Строфа II"],["v","Когда ж не стало больше пира",0,1337,0,0],["v","Ни у богов, ни у людей,",0,1338,0,0],["v","Проговорил владыка мира,",0,1339,0,0],["v","Смягчая злобу сердца ей:",0,1340,0,1],["v","\"О прелесть мира, о Хариты,",0,1340,0,0],["v","Летите в выси снеговой",0,1341,0,0],["v","К богине, горестью не сытой…",0,1342,0,0],["v","Вы мир вернете ей забытый,",0,1343,0,0],["v","О Музы, в пляске круговой…\"",0,1344,0,0],["v","Тогда впервые Афродитой",0,1345,0,0],["v","Тимпан гудящий поднят был;",0,1346,0,0],["v","В утеху ей, тоской убитой,",0,1347,0,0],["v","Он проявил свой страстный пыл…",0,1348,0,0],["v","И улыбнулась Мать святая:",0,1349,0,0],["v","Коснулась звучных флейт рукой, —",0,1350,0,1],["v","И милы ей они, взывая",0,1350,0,0],["v","К восторгу шумною игрой.",0,1351,0,0],["str","Антистрофа II"],["v","Тебя ж красавицей взрастила",0,1352,0,0],["v","В отца чертогах твоего",0,1353,0,0],["v","Судьбы загадочная сила —",0,1354,0,0],["v","Ты прогневила божество:",0,1355,0,0],["v","Высокомерно не ходила<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1356,0,0],["v","Ты к Матери на торжество…",0,1357,0,0],["v","О, что за мощь в небриде пестрой,",0,1358,0,0],["v","Небрежно спущенной с плеча,",0,1359,0,0],["v","В тебе, о тирс зелено-острый",0,1360,0,1],["v","Меж кудрей Вакхова плюща,",0,1361,0,0],["v","И в вас, крутящиеся диски,",0,1362,0,0],["v","И в вас, развитые власы,",0,1363,0,0],["v","Вакханки, нимфы, сатириски,",0,1364,0,0],["v","И лунный свет, и блеск росы…",0,1365,0,0],["v","Но для тебя все боги низки,",0,1366,0,0],["v","Поклонница своей красы!..",0,1367,0,0],["act","Действие четвертое","a5","IV"],["scene","Явление четырнадцатое","s19",5,19],["sd","Из дворца — <span class=\"ch\" data-ch=\"elena\">Елена</span> в трауре в сопровождении рабынь."],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Все хорошо устроилось, подруги.",0,1368,0,0],["v","Протея дочь не выдала: когда",0,1370,0,1],["v","Царь задавал вопросы об Атриде,",0,1370,0,0],["v","В угоду мне вещунья затаила,",0,1371,0,0],["v","Что с нами он, — сказав ему, что мертвый",0,1372,0,0],["v","Не видит солнца радостных лучей.",0,1372,0,0],["v","А <span class=\"ch\" data-ch=\"menelay\">Менелай</span>, покуда случай был,",0,1373,0,0],["v","Оружие взял лучшее — чтоб в море,",0,1374,0,0],["v","Как сказано, умершему его",0,1375,0,0],["v","В отраду погрузить. Пока ж в кольцо",0,1375,0,0],["v","Тяжелого щита продел он шуйцу",0,1376,0,0],["v","Могучую, десницу же копьем",0,1377,0,0],["v","Украсил он и долг отдать последний",0,1377,0,0],["v","Теперь готов… И неспроста он в бой",0,1378,0,0],["v","Вооружает тело: ныне храбро",0,1379,0,0],["v","Над тьмами варваров победный он",0,1380,0,1],["v","Трофей поставит сильною рукою,",0,1380,0,0],["v","Когда обещанный нас примет струг.",0,1381,0,0],["v","А как он свеж! Одеждою свои",0,1382,0,0],["v","Он заменил лохмотья — мой и выбор, —",0,1383,0,0],["v","Купелью из речной воды усталым",0,1384,0,0],["v","Дав отдых членам; а ведь уж давно",0,1385,0,0],["v","Ее он не знавал… Но вот жених мой,",0,1386,0,0],["v","Уверенный в невесте… замолчу.",0,1387,0,0],["v","И вы молчите дружелюбно: наше",0,1388,0,0],["v","Спасенье волю ведь и вам сулит.",0,1389,0,0],["scene","Явление пятнадцатое","s20",5,20],["sd","Из ворот выходит <span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>, за ним рабы, несущие или ведущие все перечисленные выше (ст. 1255 сл.) предметы. Выходит также и <span class=\"ch\" data-ch=\"menelay\">Менелай</span> в чистой, новой одежде и во всеоружии."],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Сюда, рабы: поочередно, как",0,1390,0,1],["v","Ахеец вас поставил, проносите",0,1390,0,0],["v","Свои дары: все море их возьмет…",0,1391,0,0],["v","Рабы удаляются по направлению к берегу.",0,1392,0,0],["sd","(<span class=\"ch\" data-ch=\"elena\">Елене</span>.)"],["v","А ты, жена, коль мой совет разумен,",0,1392,0,0],["v","Послушайся меня: останься здесь.",0,1393,0,0],["v","Ведь разницы не будет, от тебя ли",0,1394,0,0],["v","Получит муж покойный твой дары",0,1395,0,0],["v","Иль от другого. Мне же страшно, как бы",0,1395,0,0],["v","Ты в исступленье горя и любви",0,1396,0,0],["v","Не бросилась в морские волны, память",0,1397,0,0],["v","О прежнем муже живо воскрешая:",0,1397,0,0],["v","И здесь уж слишком плачешь ты о нем.",0,1398,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","О новый мой владыка! Тот покойный",0,1399,0,0],["v","От нас себе почета ждет, и с ним",0,1400,0,1],["v","Союз еще не порван… Если б сердца",0,1400,0,0],["v","Я слушалась, то гробовое ложе",0,1401,0,0],["v","Его делить пошла б… Но ведь царя",0,1402,0,0],["v","Не оживишь и этой жертвой… Все же",0,1402,0,0],["v","Позволь самой отдать ему дары",0,1403,0,0],["v","Загробные. Тебе ж да воздадут",0,1404,0,0],["v","Бессмертные за это по желанью",0,1405,0,0],["v","Горячему <span class=\"ch\" data-ch=\"elena\">Елены</span>… и ему,",0,1405,0,0],["v","Пособнику-ахейцу, заодно.",0,1406,0,0],["v","Во мне же ты жену найдешь такую,",0,1407,0,0],["v","Какую должен ты иметь, желая",0,1407,0,0],["v","И <span class=\"ch\" data-ch=\"menelay\">Менелаю</span> счастия, и мне.",0,1408,0,0],["v","Ведь счастье нам событья предвещают.",0,1409,0,0],["v","Но дай приказ, чтоб снарядили судно",0,1410,0,1],["v","Для тех даров — и милость доверши.",0,1410,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","одному из слуг"],["v","Ступай, и пусть сидонский им дадут",0,1411,0,0],["v","На пятьдесят гребцов корабль с народом!",0,1412,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","А управлять им должен тот, который",0,1413,0,0],["v","И похороны ведает — не так ли?",0,1414,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Конечно, он… Все слушайте его!",0,1415,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Чтоб не было сомнений, повтори…",0,1416,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Не раз, а два, коль ты того желаешь.",0,1417,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Храни ж тебя удача, да и нас.",0,1418,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Смотри ж, не слишком изнывай в слезах!",0,1419,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Мою любовь узнаешь ты сегодня.",0,1420,0,1],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Ведь мертвый — тень… и труд напрасен наш.",0,1420,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","с улыбкой"],["v","Я думаю теперь и о живом.",0,1421,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","обрадованный"],["v","О, ты со мной забудешь и Атрида…",0,1422,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Да… всем ты взял; о счастье лишь прошу.",0,1423,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Все от тебя зависит, коль полюбишь…",0,1424,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["v","Друзей давно умею я любить.",0,1425,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","все более восхищенный"],["v","Я сам согласен помогать вам, хочешь?",0,1426,0,0],["sp","<span class=\"ch\" data-ch=\"elena\">Елена</span>"],["dir","быстро и не умея скрыть испуг"],["v","Ах, что ты, царь… На это слуги есть.",0,1427,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Ну, ну, пускай… Оставим Пелопидам",0,1428,0,0],["v","Обряды их… К тому ж, когда б мой дом",0,1429,0,0],["v","Был осквернен… Но <span class=\"ch\" data-ch=\"menelay\">Менелай</span> не здесь ведь",0,1430,0,1],["v","Скончался, а далеко…",0,1430,0,0],["sd","(Слугам.)"],["v","Вы властям",0,1431,4,0],["v","Моих земель велите заготовить,",0,1432,0,0],["v","Прислужники, венчальные дары.",0,1433,0,0],["v","Египет весь пускай дрожит от кликов",0,1433,0,0],["v","Торжественных… Елена, ты моя,",0,1434,0,0],["v","И мой удел завиден будет смертным.",0,1435,0,0],["sd","(<span class=\"ch\" data-ch=\"menelay\">Менелаю</span>.)"],["v","А ты, наш гость, лишь эти погрузишь",0,1436,0,0],["v","Сокровища в пучину для Атрида,",0,1436,0,0],["v","<span class=\"ch\" data-ch=\"elena\">Елены</span> мужа первого, скорей",0,1437,0,0],["v","Назад ее вези: на брачном пире",0,1438,0,0],["v","И для тебя, ахеец, место есть…",0,1439,0,0],["v","А там — домой, а хочешь — здесь устрою…",0,1440,0,1],["sd","(Уходит со свитой.)"],["scene","Явление шестнадцатое","s21",5,21],["v","Те же без <span class=\"ch\" data-ch=\"feoklimen\">Феоклимена</span> и его свиты.",0,1418,0,0],["sp","<span class=\"ch\" data-ch=\"menelay\">Менелай</span>"],["dir","молитвенно подняв руки"],["v","О Зевс! Тебя отцом и мудрым славят:",0,1396,0,0],["v","Взгляни на нас и муки прекрати!",0,1374,0,0],["v","Все в гору, в гору катим тяжесть бедствий,",0,1351,0,0],["v","Усталые, — о, краем ты руки",0,1329,0,0],["v","К нам прикоснись, и путь наш безопасен.<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1307,0,0],["v","Довольно с нас и прежних злоключений.",0,1284,0,0],["v","Я часто, боги, призывал уж вас",0,1262,0,0],["v","И с ласковой и с горькою мольбою;",0,1240,0,0],["v","Не вечно же обязан я страдать,",0,1217,0,0],["v","Хоть раз удачи требовать я вправе.",0,1195,0,0],["v","О да, одну мне милость окажите —",0,1173,0,0],["v","И ей навеки счастлив буду я.",0,1150,0,1],["sd","(Уходит в сторону с <span class=\"ch\" data-ch=\"elena\">Еленой</span> и рабами, которые несут дары.)"],["scene","Третий музыкальный антракт","s22",5,22],["sp","Хор"],["str","Строфа I"],["v","О ладья, о дочь Сидона!",0,1151,0,0],["v","Быстровеслая, ты пену",0,1152,0,0],["v","На морских рождаешь волнах",0,1153,0,0],["v","И голубишь… а дельфины",0,1154,0,0],["v","Вкруг тебя резвятся хором",0,1155,0,0],["v","В тихий час, когда морская",0,1156,0,0],["v","Зыбь едва рябится ветром",0,1157,0,0],["v","И взывает Галанея,",0,1158,0,0],["v","Понта дочь: \"Пловцы, живее!",0,1159,0,0],["v","Парус весь вы отдавайте<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1160,0,0],["v","Ветра ровному дыханью,",0,1460,0,1],["v","В руки крепкие берите",0,1460,0,0],["v","По сосновому весельцу:",0,1461,0,0],["v","Порт вас ждет гостеприимный,",0,1462,0,0],["v","Ждет <span class=\"ch\" data-ch=\"elena\">Елену</span> дом Персея\".<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1463,0,0],["str","Антистрофа I"],["v","Может быть, теперь уж скоро",0,1464,0,0],["v","Девы-жрицы Левкиппиды<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1465,0,0],["v","Берега Еврота вместе",0,1465,0,0],["v","Попирать с тобою будут.",0,1466,0,0],["v","Через столько лет ты снова",0,1467,0,0],["v","В хоровод войдешь священный",0,1468,0,0],["v","Иль отпразднуешь, ликуя,",0,1469,0,0],["v","Ночью память Гиакинта.",0,1470,0,1],["v","Был сражен он в состязанье",0,1470,0,0],["v","Диском Феба, и лаконцам",0,1471,0,0],["v","Бог велел, чтоб в год по разу",0,1472,0,0],["v","Гиакинта поминали.",0,1473,0,0],["v","В терему своем застанешь",0,1474,0,0],["v","Ты, Елена, Гермиону:",0,1475,0,0],["v","Ей ведь брачного поныне",0,1476,0,0],["v","Светоча не зажигали.",0,1477,0,0],["str","Строфа II"],["v","О, если б на быстрых нам крыльях",0,1478,0,0],["v","Подняться в воздушные выси,",0,1479,0,0],["v","О девы, где стройной станицей",0,1480,0,1],["v","Ливийские птицы несутся!<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,1481,0,0],["v","Покинув дождливую зиму,",0,1482,0,0],["v","Летят они, кличу покорны",0,1483,0,0],["v","Той старшей сестры, что зовет их",0,1484,0,0],["v","В бездождные роскоши земли.",0,1485,0,0],["v","О спутницы туч быстробежных,",0,1486,0,0],["v","Небесные птицы! Летите,",0,1487,0,0],["v","Где путь указуют Плеяды",0,1488,0,0],["v","И блеск Ориона ночного!",0,1490,0,1],["v","На бреге Еврота веселом",0,1491,0,0],["v","Вы весть подадите селянам,",0,1492,0,0],["v","Что царь, победитель Приама,",0,1493,0,0],["v","В старинный свой дом возвратится.",0,1494,0,0],["str","Антистрофа II"],["v","На быстрых конях поднебесных",0,1495,0,0],["v","Умчитесь туда ж, Диоскуры,",0,1496,0,0],["v","Под звезд огнеметом лучистым,",0,1497,0,0],["v","Блаженные гости эфира!",0,1498,0,0],["v","Дохните на грозное море…",0,1500,0,1],["v","Валы его, темною пеной",0,1501,0,0],["v","Венчанные, нежно смирите,",0,1502,0,0],["v","Пловцам наполняя их парус",0,1503,0,0],["v","Ласкающим ветром попутным:",0,1504,0,0],["v","На помощь, на помощь <span class=\"ch\" data-ch=\"elena\">Елене</span>!",0,1505,0,0],["v","Сестры прекратите бесславье;",0,1506,0,0],["v","Пусть смолкнут позорные речи",0,1507,0,0],["v","О варварском ложе царицы;<a class=\"nr\" href=\"#n-k43\" data-n=\"k43\" aria-label=\"Примечание 43\">43</a>",0,1508,0,0],["v","Безвольная жертва раздора",0,1509,0,0],["v","Идейского, стен не видала",0,1510,0,1],["v","Она Аполлонова града!<a class=\"nr\" href=\"#n-k44\" data-n=\"k44\" aria-label=\"Примечание 44\">44</a>",0,1511,0,0],["act","Исход","a6",""],["scene","Явление семнадцатое","s23",6,23],["sd","Из ворот выходит <span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span> в брачной одежде и с пышной свитой. Через несколько минут немой сцены приготовлений к встрече <span class=\"ch\" data-ch=\"elena\">Елены</span> прибегает со стороны моря вестник — растрепанный, бледный и оборванный воин <span class=\"ch\" data-ch=\"feoklimen\">Феоклимена</span>."],["sp","Вестник"],["v","Царь, у меня дурные вести!",0,1512,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Будто?",1,1512,0,0],["sp","Вестник"],["v","Устраивай другую свадьбу. Нет",0,1513,0,0],["v","В твоей стране <span class=\"ch\" data-ch=\"elena\">Елены</span> больше, царь.",0,1514,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","А кто ж умчал ее? Стопы иль крылья?",0,1515,0,0],["sp","Вестник"],["v","Царь <span class=\"ch\" data-ch=\"menelay\">Менелай</span> на корабле увез…",0,1516,0,0],["v","Ведь это он был собственной кончины",0,1517,0,0],["v","Здесь вестником сейчас перед тобой…",0,1518,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Вот странные слова! Но где ж ладью",0,1519,0,0],["v","Нашел, чтобы уехать? Не поверю!",0,1520,0,1],["sp","Вестник"],["v","Не ты ли сам ему и судно дал?",0,1520,0,0],["v","Твои ж гребцы и увезли их в море.",0,1521,0,0],["v","Вот в кратком перечне вся весть моя.",0,1522,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Я не могу понять: да как же, вас",0,1523,0,0],["v","Была такая сила там, на веслах,",0,1524,0,0],["v","А он один? Все толком расскажи!",0,1525,0,0],["sp","Вестник"],["v","Покинув дом, спартанская царица",0,1525,0,0],["v","Держала путь на взморье и, стопы",0,1526,0,0],["v","Изнеженно с трудом передвигая,",0,1527,0,0],["v","Лукавая, изображала плач…",0,1528,0,0],["v","А муж ее был тут же, и не думал",0,1529,0,0],["v","Он умирать. Средь царских кораблей",0,1530,0,1],["v","Сидонского наметив первохода,",0,1530,0,0],["v","Спускаем судно в волны: пятьдесят",0,1531,0,0],["v","Там было мест гребцовых, да и весла",0,1532,0,0],["v","Подогнаны отлично. Целый ряд",0,1533,0,0],["v","Тут закипел работ. Кто мачту ладит,",0,1533,0,0],["v","Кто веслами занялся, паруса",0,1534,0,0],["v","Налаживать пустились, был и руль",0,1535,0,0],["v","Тем временем канатами прикручен.",0,1536,0,0],["v","Пока у нас работа шла, глядим,",0,1536,1,0],["v","Являются товарищи Атрида…",0,1537,0,0],["v","Удачно, видно, время подсмотрели.",0,1538,0,0],["v","Ну, одеянья, точно, волны им",0,1539,0,0],["v","Попортили, а сами — молодцами…",0,1540,0,1],["v","Увидев их, прикинулся Атрид,",0,1540,0,0],["v","Что крепко их жалеет он, и молвил:",0,1541,0,0],["v","\"Откуда ж вы, с какого корабля",0,1542,0,0],["v","Ахейского, товарищи невзгоды?",0,1543,0,0],["v","Иль собрались вы вместе хоронить",0,1544,0,0],["v","Погибшего Атрида? Дочь Тиндара",0,1545,0,0],["v","Заочный гроб герою припасла\".",0,1546,0,0],["v","Глядим, и те лукавцы прослезились…",0,1547,1,0],["v","И на корабль дары несут. А в нас",0,1548,0,0],["v","Уже тогда закралось подозренье,",0,1549,0,0],["v","И меж собой мы толковали: слишком",0,1550,0,1],["v","Народу, мол, набралось много; все ж",0,1550,0,0],["v","Смолчали мы на этот раз, припомнив",0,1551,0,0],["v","Твои слова. Не сам ли ты велел",0,1552,0,0],["v","Нам слушаться пришельца? Вся и смута",0,1553,0,0],["v","Из-за того… Ну, что полегче, мы",0,1554,0,0],["v","Без всякого труда в ладью спустили;",0,1555,0,0],["v","Один бычок упрямился: никак",0,1556,0,0],["v","На сходни не загнать — ревет, косится,",0,1557,0,0],["v","Кольцом весь изогнулся, а рога",0,1558,0,0],["v","Вперед: небось не тронешь… Муж Еленин",0,1559,0,0],["v","Кричит тогда: \"Гей, воины, что Трою",0,1560,0,1],["v","Разрушили, по-своему беритесь,",0,1560,0,0],["v","По-эллински! На плечи молодые",0,1561,0,0],["v","Упрямую скотину, да в ладью",0,1562,0,0],["v","На нос ее! — А сам мечом играет. —",0,1563,0,0],["v","Чтоб справить нам в честь мертвого обряд!\"",0,1564,0,0],["v","Товарищи послушались: быка",0,1565,1,0],["v","Они хватают на плечи, и мигом",0,1565,0,0],["v","На палубе упрямец. <span class=\"ch\" data-ch=\"menelay\">Менелай</span>",0,1566,0,0],["v","Тогда коня, лаская лоб и шею,",0,1567,0,0],["v","Легко увлек туда же.",0,1568,0,0],["v","Переждав,",1,1568,0,0],["v","Чтоб кончилась погрузка, Тиндарида",0,1569,0,0],["v","Красивыми ногами сходней наших",0,1570,0,1],["v","Перебрала ступени. На скамье",0,1570,0,0],["v","Очистили ей место посредине;",0,1571,0,0],["v","Поблизости покойный мнимый сел,",0,1572,0,0],["v","Другие поровну расселись, справа",0,1573,0,0],["v","И слева, муж при муже, вдоль бортов…",0,1574,0,0],["v","За пазухой ножи. Гребцам сигнал",0,1575,0,0],["v","Тогда начальник подал, и далеко",0,1575,0,0],["v","От весел шум понесся…",0,1576,0,0],["v","От земли",1,1576,0,0],["v","Порядочно отъехав, у кормила",0,1577,0,0],["v","Стоявший муж спросил: \"А что же, гость,",0,1578,0,0],["v","Нам дальше плыть прикажешь или полно?",0,1579,0,0],["v","Ты — командир«. А тот: »Останови\".",0,1580,0,1],["v","И вот с мечом в деснице на нос, видим,",0,1581,0,0],["v","Колоть быка идет. О мертвеце",0,1582,0,0],["v","Ни о каком он не молился. \"Боже, —",0,1583,0,0],["v","Он завопил, — ты, Посейдон, и вы,",0,1584,0,0],["v","Священные Нерея дщери, дайте",0,1585,0,0],["v","Живым доплыть до Навплии с женой!\"",0,1586,0,0],["v","И брызнула благим ответом в море",0,1587,0,0],["v","С железа кровь… Тут раздаются крики:",0,1588,0,0],["v","«Обман… обман!..», «Плывем назад!..», \"Бери",0,1590,0,1],["v","Команду, что ль!..«, »Обратно руль!\". Оставив",0,1590,0,0],["v","Убитого быка, тогда Агрид",0,1591,0,0],["v","К товарищам взывает: \"Не пора ли,",0,1592,0,0],["v","О цвет Эллады, варваров толпу",0,1593,0,0],["v","Кого ножом, рукой кого — да за борт?\"",0,1594,0,0],["v","Ему ж в ответ наш новый командир",0,1595,0,0],["v","Своим кричит: \"Шесты хватайте! Живо,",0,1596,0,0],["v","Кто чем горазд! Выламывай скамьи!",0,1597,0,0],["v","Вон из уключин весла, не жалейте",0,1598,0,0],["v","Ахейских черепов, покрасьте их!..\"",0,1599,0,0],["v","Мы с веслами, они с мечами — все",0,1600,1,1],["v","Вмиг на ногах… И следом покатилась",0,1600,0,0],["v","Ручьями кровь по кораблю. Жена",0,1601,0,0],["v","Атридова с кормы старалась греков",0,1602,0,0],["v","Разгорячить. \"Да точно ль Илион",0,1602,0,0],["v","Вы рушили? — кричит она. — Когда же",0,1603,0,0],["v","Вы варварам ахейцев наконец",0,1604,0,0],["v","Покажете?\" И в жаркой схватке этой",0,1604,0,0],["v","Кто падает, кто нет — глядишь, а павший",0,1605,0,0],["v","Уж трупом стал. Во всеоружье был",0,1606,0,0],["v","Царь <span class=\"ch\" data-ch=\"menelay\">Менелай</span> на страже: где его",0,1606,0,0],["v","Дружина подавалась, там железо",0,1607,0,0],["v","В его деснице гибелью сверкнет.",0,1608,0,0],["v","Египтяне, те в море побросались;",0,1608,0,0],["v","На веслах никого. Тогда Атрид",0,1609,0,0],["v","Идет к рулю и бег держать велит он",0,1610,0,1],["v","На берега Эллады. Мачту вслед",0,1610,0,0],["v","На судне поднимают, и надулся",0,1611,0,0],["v","Попутным ветром парус. Так они",0,1612,0,0],["v","И с глаз долой. Резни избегнув, в море",0,1613,0,0],["v","Спустился я у якоря и вплавь",0,1614,0,0],["v","Достиг земли. Здесь тонущему кто-то",0,1615,0,0],["v","Из рыбаков помог: и вот на берег",0,1615,0,0],["v","Я выбрался, чтоб обо всем тебе",0,1616,0,0],["v","Поведать. Так-то, царь, во всех делах",0,1617,0,0],["v","Разумное полезно недоверье.",0,1618,0,0],["sp","Корифей"],["dir","со скрытой иронией"],["v","Кто б мог подумать, что Атрид уйдет",0,1619,0,0],["v","От нашего и твоего вниманья?",0,1620,0,1],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","злобно сверкнув глазами на девушек"],["v","Женской хитростью обманут я, несчастный! Вместе с ней",0,1621,0,0],["v","Свадьбы я своей лишился… Эй, за ними! Поскорей!..",0,1622,0,0],["v","Да куда! Догонишь разве? Нет, напрасны те мечтанья…",0,1623,0,0],["v","Но, сестра! Хоть ей, преступной, я припомню злодеянья.",0,1624,0,0],["v","Знала ведь, что здесь предатель, — допустила до вреда!",0,1625,0,0],["v","Ну, другого уж вещаньем не обманет никогда!",0,1626,0,0],["sp","Вестник"],["v","Погоди, владыка: руку на кого ты поднимаешь?",0,1627,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Правосудия ищу я… Мне ты в том не помешаешь…",0,1628,0,0],["sp","Вестник"],["v","Я не выпущу одежды… Твой поступок — грех прямой!",0,1629,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Или раб царя сильнее?",0,1630,0,1],["sp","Вестник"],["v","Если воли он благой!",1,1630,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Не ко мне благоволишь ты, коль не дашь…",0,1630,0,0],["sp","Вестник"],["v","Дух злобен твой!",1,1630,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Мне убить сестру-злодейку.",0,1631,0,0],["sp","Вестник"],["v","Нет ее благочестивей.",1,1631,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Изменила!",0,1632,0,0],["sp","Вестник"],["v","То измена ль, что ты вышел справедливей?",0,1633,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Отдала жену другому!",0,1634,0,0],["sp","Вестник"],["v","Ей главой спартанец был.",1,1634,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Как? Главой моей рабыни?",0,1635,0,0],["sp","Вестник"],["v","Так отец ее судил.",1,1635,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Мне судьба ее вручила.",0,1636,0,0],["sp","Вестник"],["v","Да, но долг берет обратно.",1,1636,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Кто ж судьей тебя поставил?",0,1637,0,0],["sp","Вестник"],["v","Сам же ты, судя превратно…",1,1637,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Иль не царь я?..",0,1638,0,0],["sp","Вестник"],["v","Царь для правды, не затем, чтоб обижать…",1,1638,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["v","Или петли захотел ты?",0,1639,0,0],["sp","Вестник"],["v","Что ж! Казни! Но убивать",1,1639,0,0],["v","Я не дам тебе царевны. За господ на смерть согласен;",0,1640,0,1],["v","Жребий этот для слуги ведь благородного прекрасен.",0,1640,0,0],["scene","Явление восемнадцатое","s24",6,24],["sd","Феоклимен, выхватив меч, с яростью бросается на воина. В эту минуту с зубцов стены раздается грозный оклик; царь оглядывается и видит двух божественных юношей в пурпуровых хламидах. Это — Кастор и Полидевк."],["sd","Кастор"],["v","Сдержи свой гнев несправедливый, царь",0,1641,0,0],["v","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>. Ты внемлешь Диоскурам:",0,1642,0,0],["v","Мы Ледою и вместе рождены",0,1643,0,0],["v","С <span class=\"ch\" data-ch=\"elena\">Еленою</span>, которая дворец твой",0,1643,0,0],["v","Покинула сегодня. К свадьбе ты",0,1644,0,0],["v","Стремился недозволенной, и гневу",0,1645,0,0],["v","Нет места твоему. Не оскорбила",0,1646,0,0],["v","Тебя сестра, морской богини дочь,",0,1646,0,0],["v","Царевна <span class=\"ch\" data-ch=\"feonoya\">Феоноя</span>, тем, что волю",0,1647,0,0],["v","Богов и вашего отца заветы",0,1648,0,0],["v","Твоей неправой страсти предпочла.",0,1649,0,0],["v","А твой чертог <span class=\"ch\" data-ch=\"elena\">Елене</span> не навек,",0,1650,0,1],["v","А лишь поднесь назначен был. Твердыни",0,1651,0,0],["v","Троянские во прахе, и не нужно",0,1652,0,0],["v","Ей более давать богам свое",0,1653,0,0],["v","На поруганье имя. Брак и дом",0,1654,0,0],["v","Возвращены <span class=\"ch\" data-ch=\"elena\">Елене</span>.",0,1655,0,0],["v","Ты же злой",1,1655,0,0],["v","Не поднимай на <span class=\"ch\" data-ch=\"feonoya\">Феоною</span> меч…",0,1656,0,0],["v","Она разумно рассудила. Мы бы",0,1657,0,0],["v","Сестру и раньше вызволить могли,",0,1658,0,0],["v","В бессмертных сонм возведены Зевесом;",0,1659,0,0],["v","Но иначе судила божья воля",0,1660,0,1],["v","И рока власть — им покорились мы.",0,1660,0,0],["v","Мои слова тебе я уж сказал;",0,1661,1,0],["v","К <span class=\"ch\" data-ch=\"elena\">Елене</span> речь несется Диоскуров:",0,1662,0,0],["v","Плыви, сестра! С тобой любимый муж,",0,1662,0,0],["v","И ласково попутный ветер веет;",0,1663,0,0],["v","Мы ж, близнецы, твои родные братья,",0,1664,0,0],["v","Проводим вас до берегов родных,",0,1665,0,0],["v","Над вами пролетая, невредимо.",0,1665,0,0],["v","Когда ж пройдешь стезю свою земную,",0,1666,0,0],["v","Богинею <span class=\"ch\" data-ch=\"elena\">Елену</span> нарекут,<a class=\"nr\" href=\"#n-k45\" data-n=\"k45\" aria-label=\"Примечание 45\">45</a>",0,1667,0,0],["v","И долю ты получишь в возлияньях",0,1667,0,0],["v","И трапезах от смертных, как и мы.",0,1668,0,0],["v","Так Зевс велел. А остров тот, где, Майей",0,1669,0,0],["v","Рожденный, бог тебе твой бег небесный",0,1670,0,1],["v","Определил, похитивши тебя",0,1670,0,0],["v","Из Спарты, чтоб женою ты не стала",0,1671,0,0],["v","Парису, — остров, что каймою длинной",0,1672,0,0],["v","Вдоль Аттики расположился, брег",0,1673,0,0],["v","Ее блюдя, — <span class=\"ch\" data-ch=\"elena\">Еленой</span> назван будет<a class=\"nr\" href=\"#n-k46\" data-n=\"k46\" aria-label=\"Примечание 46\">46</a>",0,1674,0,0],["v","Людьми за то, что дал приют тебе.",0,1675,0,0],["v","А <span class=\"ch\" data-ch=\"menelay\">Менелай</span>-скиталец волей рока",0,1676,0,0],["v","Блаженные получит острова.<a class=\"nr\" href=\"#n-k47\" data-n=\"k47\" aria-label=\"Примечание 47\">47</a>",0,1677,0,0],["v","Ведь к благородным милостивы боги;",0,1678,0,0],["v","Лишь низкой черни горесть суждена.",0,1679,0,0],["sp","<span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span>"],["dir","в покорной осанке"],["v","О Леды и Зевеса сыновья!",0,1680,0,1],["v","Угас пожар, что разгорелся в сердце",0,1680,0,0],["v","Из-за сестры, владыки, вашей. Мир",0,1681,0,0],["v","И со своей сестрой я заключу",0,1682,0,0],["v","И — если боги так велят — <span class=\"ch\" data-ch=\"elena\">Елене</span>",0,1683,0,0],["v","Счастливого возврата пожелаю.",0,1683,0,0],["v","Нет доблестней ее, нет и верней, —",0,1684,0,0],["v","Она достойная сестра бессмертных.",0,1685,0,0],["v","О, радуйтесь, блаженные, сестре,",0,1686,0,0],["v","Благословенной между жен земных.",0,1686,0,0],["v","Видение исчезает. <span class=\"ch\" data-ch=\"feoklimen\">Феоклимен</span> со свитой — в дом.",0,1687,0,0],["sp","Хор"],["dir","покидая орхестру"],["v","Воли небесной различны явленья,",0,1688,0,0],["v","Люди не могут ее угадать:",0,1689,0,0],["v","Многого ждем мы, чему не свершиться",0,1690,0,1],["v","Бог же укажет нежданному путь…",0,1691,0,0],["v","Так эта кончилась драма.",0,1692,0,0],["h1","Комментарий","comm"],["p","Трагедия поставлена в 412 г. до н.э. вместе с несохранившейся «Андромедой»; год спустя они обе стали предметом пародирования в комедии Аристофана «Женщины на празднике Фесмофорий»."],["p","Для «Елены» Еврипид обработал вариант мифа, восходящий, возможно, уже к Гесиоду и, во всяком случае, разработанный Стесихором. Согласно преданию, этот поэт написал сначала хоровую поэму «Елена», в которой изложил обычную версию мифа о похищении спартанской царицы, и за это его постигла слепота, насланная божественными братьями Елены — Диоскурами. Узнав о причине их гнева, Стесихор сочинил так называемую палинодию («обратную песнь»), в которой дело излагалось таким образом, что Парис похитил из дома Менелад и привез в Трою только призрак Елены; из-за него и разгорелась десятилетняя война, в то время как истинная, ни в чем не повинная Елена была, по приказу Зевса (или Геры), перенесена в Египет и вручена мудрому старцу Протею, царившему на острове Фаросе (см. ст. 31 — 36,42 — 48, 241 — 251,582 — 588, 666 — 683). Ему было приказано беречь Елену до тех пор, пока Менелай после взятия Трои не будет волей судьбы также приведен на Фарос, где он и встретит свою супругу. Еврипид осложнил стесихоровскую версию только в том отношении, что приурочил действие трагедии к моменту, когда Протей уже умер и его сын, новый царь Феоклимен, посягает на ложе Елены (ст. 60 — 67, 783 — 799). Это нововведение дало Еврипиду возможность построить пьесу как трагедию интриги, что он удачно сделал прежде в «Ифигении в Тавриде»."],["p","Если оставить в стороне рассказ о божественном вмешательстве, приведшем к ослеплению, а затем к прозрению Стесихора, то легко будет понять, что поэт избрал новый вариант мифа под давлением спартанцев. Столь же естественно предположить, что и Еврипид, рисующий Елену в самом неприглядном свете во всех произведениях, как предшествующих «Елене» (в «Андромахе», «Троянках», «Ифигении в Тавриде», «Электре»), так и в хронологически следующих за ней (особенно в «Оресте»), ставил перед собой в этой трагедии какие-то особые задачи, заставившие его принять пролаконский вариант мифа. Ответ на вопрос дает отчасти сам Еврипид в ст. 1151 — 1164, проникнутых стремлением к миру между воюющими странами, и пацифистская установка поэта в этой трагедии не вызывает у исследователей сомнения. Труднее объяснить, как могли афинские власти, предварительно рассматривавшие представленные для состязания произведения, допустить к постановке трагедию с проспартанской тенденцией, после того как спартанцы, захватив в 413 г. селение Декелею, в двадцати километрах от Афин, снова начали опустошать землю Аттики. Это соображение заставляет некоторых исследователей (правда, очень немногочисленных) не доверять прямому смыслу использованного Еврипидом мифа и искать в поведении Елены и в этой трагедии свойственные ей в других произведениях драматурга распущенность нрава, тайную симпатию к Парису, хитрость и изворотливость в обращении с Менелаем. Однако подтвердить такую характеристику Елены развитием сюжета и текстом разбираемой трагедии представляется весьма затруднительным, и временную перемену в отношении Еврипида к образу спартанской царицы надо признать фактом, все еще нуждающимся в объяснении."],["p","Перевод И. Анненского (сделанный, по-видимому, ок. 1906 г., когда он уже охладел к своему Еврипиду) известен только по посмертной публикации Ф. Ф. Зелинского («Театр Еврипида», II, 1917). По словам Зелинского, перевод остался черновым, и в нем «пришлось изменить довольно много стихов не столько ошибочных, сколько слабых, вялых или не выдержанных по настроению» (с. 471). Так как рукопись Анненского, по-видимому, не сохранилась, перевод печатается по первой публикации, т. е. более чем на треть переписанный Зелинским. Изменено только оформление рубрикации и списка действующих лиц."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"],["note","k43"],["note","k44"],["note","k45"],["note","k46"],["note","k47"]],"n":{"k1":["Ст. 2 — 3. …он поит, лишь снег сойдет… поля…","Разливы Пила в V в. нередко объясняли таянием снегов на вершинах гор, откуда он якобы берет начало; эту теорию выдвигал, в частности, Анаксагор, которому Еврипид во многом был обязан своим философским образованием."],"k2":["Ст. 7. Псамафа (от греч. psamathos","«песок») — Нереида («одна из дев пучинных»), обладавшая способностью принимать различные образы. Укрощенная, несмотря на все ее уловки, Эаком, она родила ему сына Фока (по-греч. phocos — «тюлень»). Поскольку гомеровский Протей также умел изменять свою внешность, а тюлени были его любимыми животными (см. «Одиссея», IV, 403 — 413), то естественно, что традиция сделала затем Псамафу женой Протея и матерью его детей."],"k3":["Ст. 13. Феоноя.","Это имя значит «обладающая божественным разумом»."],"k4":["Ст. 15","От древнего Иерея… — Так как гомеровский Протей превратился у Еврипида в благочестивого царя, то пророческие способности Феоное пришлось заимствовать у своего деда по матери, морского старца Нерея."],"k5":["Ст. 27 — 28. Парис","собственное имя троянского царевича; Александр («отразитель мужей») — почетное прозвище, полученное еще в молодости, когда он был пастухом; Идей — его имя по горе Иде, где он пас стада."],"k6":["Ст. 37 — 41","Троянская война объяснялась замыслом Зевса облегчить бремя Земли уже в послегомеровской поэме «Киприи»."],"k7":["Ст. 52. Скамандр","река на Троянской равнине."],"k8":["Ст. 88","История Аякса Саламинского, брата Тевкра, — тема сохранившейся трагедии Софокла «Аякс»; но Еврипид держится ближе к его предшественнику Эсхилу."],"k9":["Ст. 99. Он сватался к Елене…","Откуда Еврипид почерпнул сведения об участии Ахилла в сватовстве Елены, трудно сказать. Гесиодовский «Каталог женщин» специально подчеркивает, что кентавр Хирон, наставник Ахилла, удержал юношу от этого предприятия; в противном случае Менелаю не удалось бы добиться ее руки."],"k10":["Ст. 116. …за косу золотую…","См. «Троянки», ст. 880 — 882."],"k11":["Ст. 136. Так говорят.","О самоубийстве Леды из других источников ничего не известно."],"k12":["Ст. 164 — 252","Построение парода, в котором монодиям Елены соответствуют строфы хора, подобно построению соответствующих разделов в «Электре», ст. 167 — 212."],"k13":["Ст. 168. Сирены","здесь не гомеровские волшебницы, зачаровывающие песней мореходов, а музы погребального плача, часто изображавшиеся на аттических надгробиях."],"k14":["Ст. 192 сл. Добыча диких скитальцев…","Из слов Елены видно, что хор составляют эллинские девушки, захваченные пиратами и проданные в Египет."],"k15":["Ст. 227 — 229. Афины ж медного дома…","Имеется в виду храм Афины Меднозданной (Халкиойки), получившей свое наименование по медной облицовке стен храма. Он являлся одним из самых важных святилищ в Спарте."],"k16":["Ст. 256","После этого стиха в рукописях следуют ст. 257 — 259, принятые рядом издателей за неподлинные и Анненским не переведенные: «Ведь не было случая, чтобы у эллинов или варваров женщина снесла яйцо, как говорят, родила меня Леда от Зевса». Издатели, исключающие эти стихи из текста, ссылаются на ст. 17 — 21, где Елена выражает сомнение в своем происхождении от Зевса; однако миф о рождении Елены от союза Леды с Зевсом, явившимся к ней в образе лебедя, впервые вводится в литературу как раз Еврипидом в произведениях последних лет его жизни (см. «Елена», ст. 214, 1144; «Орест», ст. 1387; «Ифигения в Авлиде», ст. 793 — 797)."],"k17":["Ст. 276. Все","рабы ведь у варваров… — Обычная для общественной мысли афинян характеристика «варваров» как рабов единодержавного деспота."],"k18":["Ст. 375 сл. Каллисто","аркадская нимфа, отдавшаяся Зевсу. Согласно различным вариантам мифа, то ли разгневанная Гера превратила ее в медведицу, то ли сам Зевс, чтобы скрыть Каллисто от Геры."],"k19":["Ст. 381 — 384","Еврипид излагает здесь вкратце какой-то местный миф, бытовавший на о. Кос и подробнее не известный."],"k20":["Ст. 384","Еще один пример очень редкого в античной драме ухода хора с орхестры посередине пьесы (см. примеч. к «Алькесте», ст. 747 сл.). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Алькеста», Ст. 747.</b> Относительно редкий случай в древнегреческой трагедии, когда хор покидает орхестру, чтобы снова вернуться перед заключительной частью драмы (ст. 861 сл.). Аналогичный прием в «Аяксе» Софокла (ст. 813 сл. и 866).</span><!--/xn-->"],"k21":["Ст. 395","Им не навязан был я… — Полемическое опровержение традиционного варианта мифа, согласно которому Тиндарей обязал женихов Елены мстить за возможное оскорбление супружеского ложа ее будущего избранника. Этот мотив встречается уже у Гомера («Илиада», П, 339 — 341); особенно подробно он был развит у Гесиода, затем у Огесихора в поэме «Елена» и принят самим Еврипидом (см. «Ифигения в Авлиде», ст. 51 — 70)."],"k22":["Ст. 619 — 621","Зелинский сохраняет в примечании не совсем понятный перевод Анненского:<br>Но так<br>Не поступай вторично. Мало ль муки<br>Из-за тебя под Илионом муж<br>С ахейцами делил — и понапрасну."],"k23":["Ст. 636 — 645","Этот монолог, переведенный ямбами, представляет в оригинале небольшую монодию."],"k24":["Ст. 640. Чета блаженных бемквнных","Диоскуры; предполагается, что они присутствовали на свадьбе Елены и Менелая."],"k25":["Ст. 747 — 757","Еврипид разделяет со своими согражданами негодование по адресу прорицателей и оракулов, которых афиняне в это время обвиняли в неудачном исходе Сицилийской кампании (ср. Фукидид, Vin, I, 1: «Узнав потом истину [о поражении], афиняне… сердились на истолкователей оракулов, гадателей, вообще на всех тех, кто в то время именем божества внушил им надежду на завоевание Сицилии»)."],"k26":["Ст. 766 — 769","На обратном пути из Трои ахейские корабли попали в Эгейском море в сильную бурю (см. Эсхил, «Агамемнон», ст. 650 — 660; Еврипид, «Троянки», ст. 77 — 94), во время которой многие погибли. Старец Еврейский — Навплий, отец Паламеда, казненного греками под Троей по ложному обвинению; чтобы отметить им за смерть сына, Навплий при приближении уцелевших от бури кораблей к Евбее зажег ложный маяк над подводными утесами («огни коварные»), на которых разбились многие корабли. Сам Менелай был застигнут новой бурей у мыса Малеи (см. ст. 1132), отнесен далеко на запад и во время своих семилетних скитаний (см. ст. 775 сл.) посетил и критские города, и ливийские гавани. Под нагорными вышками Персея разумеется какая-то область в Ливии, где Персей спас от морского чудовища прикованную к скале Андромеду. Этот миф был обработан Еврипидом в трагедии «Андромеда», поставленной одновременно с «Еленой», но не сохранившейся."],"k27":["Ст. 849. Нестор оплакивал дитя свое","юного и отважного Антилоха, который погиб под Троей от руки царя эфиопов Мемнона, спасая жизнь своего отца (см. «Одиссея», III, 111 сл.; IV, 186-188)."],"k28":["Ст. 878 — 886","О споре между богами по поводу возвращения Менелая на родину из других источников ничего не известно. Непонятно также, почему Гера должна была когда-то гневаться на Менелая: в «Одиссее» указывается, что он вынужден был скитаться, так как не совершил вовремя гекатомбы Зевсу и прочим богам (IV, 472 — 480). Скорее всего, этот эпизод — изобретение самого Еврипида, сделанное по образцу совета богов, призванного решить участь Одиссея («Одиссея», I, 22 — 93; V, 2 — 27)."],"k29":["Ст. 894 — 995","Речи Елены и Менелая, хотя и не являются частями агона, абсолютно равновелики."],"k30":["Ст. 903 — 908","Некоторые издатели считают эти стихи подложными; однако Еврипиду свойственно влагать в уста своих героев рассуждения на этические темы, только отдаленно связанные с содержанием трагедии."],"k31":["Ст. 1001 — 1004","Зелинский в примечаниях приводит перевод Анненского (сделанный по другому чтению еврипидовского текста):<br>Это сердце -<br>Святилище великой Правды; им<br>Нерею я обязана, и будет<br>Спасен Атрид, поскольку в наших силах<br>Его спасти…"],"k32":["Ст. 1089. Следы ногтей кровавые…","Раздирание щек в кровь составляло обязательный атрибут погребального вопля."],"k33":["Ст. 1098. Дочь Дионы.","Афродита, по одному из вариантов мифа — дочь Зевса и древнего женского божества Дионы."],"k34":["Ст. 1129 — 1131. Там, на Евбее, огни он зажег…","Речь идет снова о Навплии (см. примеч. к ст. 766 — 769). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 766 — 769.</b> На обратном пути из Трои ахейские корабли попали в Эгейском море в сильную бурю (см. Эсхил, «Агамемнон», ст. 650 — 660; Еврипид, «Троянки», ст. 77 — 94), во время которой многие погибли. Старец Еврейский — Навплий, отец Паламеда, казненного греками под Троей по ложному обвинению; чтобы отметить им за смерть сына, Навплий при приближении уцелевших от бури кораблей к Евбее зажег ложный маяк над подводными утесами («огни коварные»), на которых разбились многие корабли. Сам Менелай был застигнут новой бурей у мыса Малеи (см. ст. 1132), отнесен далеко на запад и во время своих семилетних скитаний (см. ст. 775 сл.) посетил и критские города, и ливийские гавани. Под нагорными вышками Персея разумеется какая-то область в Ливии, где Персей спас от морского чудовища прикованную к скале Андромеду. Этот миф был обработан Еврипидом в трагедии «Андромеда», поставленной одновременно с «Еленой», но не сохранившейся.</span><!--/xn-->"],"k35":["Ст. 1173 — 1176. Ахеец объявился…","От кого Феоклимен успел узнать о появлении в его владениях ахейца, остается неизвестным."],"k36":["Ст. 1241 — 1252","Обряд, описываемый Еленой египтянину, фантастичен: на самом деле утонувшим в море ставилась «пустая гробница» (кенотаф) на суше."],"k37":["Ст. 1301 — 1368","— «дифирамбический стасим» такого же типа, как в «Ифигении в Тавриде» (см. примеч. к ст. 1234 — 1283). Содержание его составляет, как и там, «священное повествование» — на этот раз о похищении Аидом Персефоны, дочери богини земледелия и плодородия Деметры. Последняя при этом отождествляется с фригийской Великой Матерью — богиней Кибелой (Мать блаженных, гор царица, мчащаяся в колеснице с львиной запряжкой), экстатический культ которой сближался с шумным, оргиастическим ритуалом Диониса. Смысл ст. 1353 — 1357 остается не вполне ясным: с какой стати спартанка Елена должна была посещать празднества фригийской Матери или даже афинские таинства в честь Деметры? Некоторые ученые видят здесь намек на положение дел в современных Еврипиду Афинах, где неудачи в ходе Пелопоннесской войны вызвали падение религиозного благочестия. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ифигения в Тавриде», Ст. 1234-1283.</b> «Дифирамбический стасим» (см. примеч. к «Гекубе», ст. 905-952), почти не связанный с содержанием трагедии. Речь идет об учреждении дельфийского прорицалища Аполлона. Первоначально здесь находился оракул Фемиды, охраняемый драконом Пифоном: убив дракона, Аполлон завладел прорицалищем. Несколько иначе этот миф излагается в так называемом гомеровском гимне к Аполлону Пифийскому (ст. 171-196) и в «Евменидах» Эсхила, ст. 1-20. В антистрофе (1259 сл.) используется, по-видимому, какая-то храмовая легенда о соперничестве Аполлона с бывшей владелицей прорицалища.</span><!--/xn-->"],"k38":["Ст. 1353 — 1356","переведены Зелинским; у Анненского было (вопреки еврипидовскому мифу, по которому настоящая Елена с Парисом не соединялась):<br>Огнем лукавым опалила<br>В покое брачном ты того,<br>Чья страсть два войска погубила, -<br>Но ты дразнила божество."],"k39":["Ст. 1458. Галанея.","В такой форме имя нигде больше не засвидетельствовано, но в «Теогонии» Гесиода среди нереид упоминается Галена- персонификация спокойного моря. Таковы же, несомненно, здесь функции Галанеи."],"k40":["Ст. 1464. Дом Персея","Аргос, родина Данаи, матери Персея. Целью Менелая является, собственно, Спарта, но Еврипид помнил о том варианте мифа, по которому Менелай причалил сначала в Навплию, чтобы похоронить в Аргосе Клитемнестру (см. ниже, ст. 1586, а также «Электра», ст. 1278 — 1280, и примеч. к «Оресту», ст. 362 — 374). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Орест», Ст. 362 — 374. Главк.</b> морское божество, обладавшее даром прорицания, — играет здесь роль, которую в «Одиссее» исполняет Протей (см. IV, 512 — 547). Свое прибытие в Навплию Менелай объясняет как раз полученным от Главка известием: оно заставило его изменить маршрут и вместо Спарты направиться в Аргос, разумеется, по суше, так как водного пути между Навплией и Аргосом нет. Поэтому слова «сюда Елена… стиралась плыть» — недосмотр переводчика.</span><!--/xn-->"],"k41":["Ст. 1466. Левкиппиды","женские спартанские божества, по преданию, двоюродные сестры и супруги Диоскуров; жрицы их святилища, о которых идет здесь речь, также назывались Левкиппидами."],"k42":["Ст. 1478 — 1494. Ливийские птицы","журавли. Образ журавлей, улетающих зимой в южные страны, известен в греческой литературе уже со времен эпоса («Илиада», III, 3 — 5; Гесиод, «Труды и Дни», ст. 448 — 450). Особенность этой картины у Еврипида состоит в том, что, вспоминая о перелете журавлей с севера на юг, хор напутствует их пожеланиями, подходящими только для перелета с юга (из Африки) на север (в Спарту)."],"k43":["Ст. 1508. Идейский раздор","спор трех богинь, завершившийся судом Париса на горе Иде."],"k44":["Ст. 1511. Аполлонов град","Троя (см. примеч. к «Андромахе», ст. 1009 — 1026). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Андромаха», Ст. 1009-1026.</b> По старинному преданию, Аполлон вместе с «царем морей» Посейдоном в течение года находились в услужении у троянского царя Лаомедонта, для которого они возвели мощные крепостные стены Трои. Однако Лаомедонт не заплатил им обещанной платы, чем в «Илиаде» и объясняется нена- висть Посейдона к троянцам (XXI, 441 — 460).</span><!--/xn-->"],"k45":["Ст. 1666 — 1669. Богинею Елену нарекут…","В Спарте существовал культ Елены, бывшей в глубокой древности местным божеством растительности и плодородия."],"k46":["Ст. 1674. …Еленой назван будет…","У юго-восточной оконечности Аттики действительно расположен остров, носивший в древности имя Елены (нынешний Макронисос); здесь, по преданию, Парис и Елена сделали первую остановку по дороге в Трою. При варианте мифа, принятом здесь Еврипидом, Гермесу совершенно не по пути было останавливаться на этом острове, лежащем на северо-восток от прямой дороги из Спарты в Египет. По-видимому, Еврипида такая несообразность не беспокоила."],"k47":["Ст. 1676 сл. …Менелай… блаженные получит острова.","О том же пророчествует Протей в «Одиссее», IV, 561 — 568."]},"mainEnd":2681,"c":[{"id":"elena","name":"Елена","role":"Жена Менелая, дочь Зевса и Леды","intro":"Царица, которую боги унесли в Египет, послав в Трою вместо неё призрак.","arc":"Еврипид развивает версию Стесихора: под Троей десять лет сражались за облачный призрак, а настоящая Елена хранила верность мужу под защитой царя Протея. Теперь Протей умер, и его сын Феоклимен силой хочет на ней жениться. Елена страдает от позора, которого не заслужила, — её проклинают все эллины. Встретив Менелая, она становится душой интриги: придумывает мнимые похороны мужа и обманывает царя. Пьеса — почти романтическая комедия с узнаванием и счастливым бегством.","st":[{"i":108,"p":4,"l":"Пролог · явление первое","t":"Пролог","d":"У гробницы Протея рассказывает о призраке, о Троянской войне, которой не была причиной, и о сватовстве Феоклимена.","c":"","k":false},{"i":291,"p":11,"l":"Пролог · явление второе","t":"Весть от Тевкра","d":"Тевкр, не узнав её, рассказывает о падении Трои и о слухах, что Менелай погиб.","c":"Надежда на мужа почти исчезает.","k":false},{"i":593,"p":22,"l":"Действие первое · Сцена плача","t":"Плач","d":"С хором оплакивает свою участь и гибель стольких людей из-за её имени.","c":"","k":false},{"i":962,"p":36,"l":"Действие второе · явление седьмое","t":"Встреча у гробницы","d":"Узнаёт в чужеземце Менелая, но тот не верит: его Елена ждёт в пещере у моря.","c":"","k":false},{"i":1241,"p":46,"l":"Действие второе · явление восьмое","t":"Узнавание","d":"Слуга сообщает, что призрак улетел на небо, — и Менелай обнимает жену.","c":"Ложь десятилетней войны раскрыта.","k":true},{"i":1661,"p":62,"l":"Действие второе · явление десятое","t":"Мольба к Феоное","d":"Умоляет пророчицу не выдавать брату Менелая.","c":"","k":false},{"i":1776,"p":66,"l":"Действие второе · явление одиннадцатое","t":"План бегства","d":"Придумывает инсценировку: Менелай будто бы утонул, и ей нужен корабль для морских похорон.","c":"","k":false},{"i":2117,"p":79,"l":"Действие третье · явление тринадцатое","t":"Обман Феоклимена","d":"В трауре, с обрезанными волосами, обещает стать женой царя после похорон и получает корабль.","c":"Её хитрость решает исход.","k":true}],"gen":"Елена"},{"id":"menelay","name":"Менелай","role":"Царь Спарты","intro":"Потерпевший кораблекрушение герой, нашедший в Египте подлинную жену.","arc":"Менелай появляется в лохмотьях из обломков паруса, и над ним смеётся старая привратница — почти комическая фигура. Но он твёрд перед опасностью и готов вместе с женой умереть. В бегстве он снова становится воином: вестник расскажет, как он перебил египтян на корабле.","st":[{"i":657,"p":25,"l":"Действие первое · явление четвертое","t":"Выброшен на берег","d":"Рассказывает о скитаниях после Трои; оставил «Елену» с товарищами в пещере.","c":"","k":false},{"i":753,"p":28,"l":"Действие первое · явление пятое","t":"У ворот","d":"Привратница гонит его прочь: царь убивает эллинов, и здесь живёт «Елена, дочь Зевса».","c":"Загадка второй Елены.","k":false},{"i":1241,"p":46,"l":"Действие второе · явление восьмое","t":"Узнавание","d":"Убеждается, что перед ним настоящая жена.","c":"","k":true},{"i":1661,"p":62,"l":"Действие второе · явление десятое","t":"Перед Феоноей","d":"Гордо заявляет, что лучше умрёт, чем отступится от жены.","c":"","k":false},{"i":2610,"p":97,"l":"Исход · явление семнадцатое","t":"Бегство","d":"Вестник рассказывает, как Менелай с товарищами захватил корабль и ушёл в море.","c":"","k":false}],"gen":"Менелай"},{"id":"feonoya","name":"Феоноя","role":"Пророчица, сестра Феоклимена","intro":"Дева-пророчица, знающая волю богов.","arc":"Феоноя оказывается в центре спора богов: Гера хочет спасти Менелая, Афродита — погубить. Она выбирает справедливость и память отца, хотя рискует жизнью.","st":[{"i":1661,"p":62,"l":"Действие второе · явление десятое","t":"Выбор правды","d":"Решает не говорить брату о Менелае: чтить справедливость и волю покойного отца.","c":"От её молчания зависит спасение.","k":true}]},{"id":"feoklimen","name":"Феоклимен","role":"Царь Египта, сын Протея","intro":"Царь, желающий силой взять Елену в жёны.","arc":"Феоклимен груб и подозрителен, но легко поддаётся на лесть и обман. Узнав о бегстве, он в ярости хочет убить сестру, но Диоскуры объявляют волю богов.","st":[{"i":1876,"p":70,"l":"Действие третье · явление двенадцатое","t":"Возвращение с охоты","d":"Узнаёт, что в страну проник эллин.","c":"","k":false},{"i":2117,"p":79,"l":"Действие третье · явление тринадцатое","t":"Обманут","d":"Верит, что Менелай утонул, и даёт корабль для похорон.","c":"","k":false},{"i":2610,"p":97,"l":"Исход · явление семнадцатое","t":"Весть о бегстве","d":"Узнаёт от вестника, что Елена бежала с мужем.","c":"","k":false},{"i":2680,"p":100,"l":"Исход · явление восемнадцатое","t":"Гнев и покорность","d":"Хочет убить сестру; Диоскуры останавливают его, и он смиряется.","c":"","k":true}]}]};
